const cp = (seed: PersonaSeed): PersonaTerm => {
  const ontologyLevel = seed.ontologyLevel ?? 1;
  const eras = cleanPersonaEras(seed.eras ?? modernCombatEras);
  const risk = seed.risk ?? (ontologyLevel >= 4 ? 'medium' : 'clean');
  const controls = Array.from(new Set([...baseControls, ...(seed.controls || [])]));
  const eraMode = personaEraModeFor(eras, seed.eraMode);
  return {
    id: `cd_persona_combat_${seed.id}`,
    name: seed.name,
    nameEn: seed.nameEn,
    group: seed.group,
    groupEn: seed.groupEn,
    def: seed.def,
    defEn: seed.defEn,
    personaCategory: '武装 / 战斗体系 / 暴力职业',
    personaCategoryEn: 'Armed / Combat System / Violence Profession',
    personaSubgroup: seed.group.replace(/^[A-J]\.\s*/, ''),
    personaSubgroupEn: seed.groupEn.replace(/^[A-J]\.\s*/, ''),
    personaKind: seed.name,
    personaKindEn: seed.nameEn,
    personaStrength: ontologyLevel >= 4 ? 'strong' : ontologyLevel >= 2 ? 'medium' : 'light',
    isCompoundPersona: true,
    ontologyLevel,
    eraMode,
    eras,
    risk,
    affects: controls,
    controls,
    forbids: Array.from(new Set([...(seed.forbids || []), ...defaultForbids])),
    absorptionRule: seed.absorptionRule || `外来元素优先折译为“${seed.name}”的战斗功能、制服/装具、训练痕迹、危险处置姿态、道具流程或制度位置，不要直接堆成无关服装奇观或武器清单。`,
    absorptionRuleEn: seed.absorptionRuleEn || `Translate outside elements into the combat function, uniform/gear, training traces, danger-handling posture, prop workflow, or institutional position of "${seed.nameEn}"; do not stack them into unrelated costume spectacle or weapon lists.`,
    tags: Array.from(new Set(['persona', 'combat', 'armed', 'compound_persona', ...(seed.tags || [])])),
    realityTags: seed.realityTags || personaRealityTagsFor(ontologyLevel, ['combat', 'armed']),
    categoryFit: seed.categoryFit || combatFitOverrides[seed.id] || combatFit(seed.group),
    styleTags: Array.from(new Set(['combat', 'armed', ...(seed.styleTags || []), ...(seed.tags || [])])),
    timeTags: eras
  };
};

const seeds: PersonaSeed[] = [
  { id: 'modern_tactical_mercenary', name: '现代战术佣兵', nameEn: 'Modern Tactical Mercenary', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是被任务雇佣关系塑形的现代战术人员。造型入口：模块胸挂、防弹织物、磨旧任务包和快拆扣让身体像一套可重组工具。母题：国家之外的专业暴力。张力：他看似自由，实际被合同、风险和撤离路线控制。视觉证据：无国籍臂章、磨损护膝、压低帽檐、警觉肩颈、贴身通讯线和不完全放松的持物手。边界：避免堆枪械或写成普通酷黑特工。', defEn: 'First read: a modern tactical operator shaped by hired mission work. Styling entry: modular chest rig, ballistic fabric, worn mission pack, and quick-release buckles make the body read as a reconfigurable tool. Motif: professional violence outside the state. Tension: he appears free but is controlled by contracts, risk, and extraction routes. Visual evidence: stateless patch, worn knee pads, lowered brim, alert neck and shoulders, close communication cable, and hands never fully relaxed. Boundary: avoid firearm piles or generic cool black-ops styling.', tags: ['tactical', 'mercenary', 'modern'] },
  { id: 'private_military_contractor', name: '私人军事承包商', nameEn: 'Private Military Contractor', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是把战争做成商业服务的私人军事承包商。造型入口：沙色战术服、承包商臂章、墨镜和无国籍装备编号。母题：公司化暴力进入冲突现场。张力：他有军人技术，却没有传统军队的荣誉叙事。视觉证据：干净但实用的靴子、卫星电话、合同文件袋、车队尘土、警惕微笑和像保镖又像士兵的站位。边界：避免写成正规军英雄或单纯反派雇佣兵。', defEn: 'First read: a private military contractor turning war into commercial service. Styling entry: tan tactical wear, contractor patch, sunglasses, and stateless equipment serials. Motif: corporate violence entering conflict zones. Tension: he has military technique without the honor story of a traditional army. Visual evidence: clean but practical boots, satellite phone, contract folder, convoy dust, guarded smile, and a stance between bodyguard and soldier. Boundary: avoid regular army heroism or simple villain mercenary tropes.', risk: 'medium', tags: ['pmc', 'contractor', 'tactical'] },
  { id: 'swat_breacher', name: 'SWAT破门手', nameEn: 'SWAT Breacher', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是冲在城市入口点前的SWAT破门手。造型入口：重型护具、破门槌、面罩、护目镜和贴墙压低的身体。母题：把一扇门变成危险阈限的人。张力：力量很重，但动作必须短、快、服从队形。视觉证据：盾牌边缘、肩部承重、门框碎屑、手套磨损、呼吸被面罩压住和准备撞入的前倾重心。边界：避免变成游戏突击兵或纯爆破场面。', defEn: 'First read: a SWAT breacher at the urban point of entry. Styling entry: heavy armor, breaching ram, mask, goggles, and a wall-hugging lowered body. Motif: the person who turns a door into a danger threshold. Tension: power is heavy, but movement must stay short, fast, and team-bound. Visual evidence: shield edge, loaded shoulders, doorframe debris, worn gloves, breath trapped by mask, and forward weight ready to enter. Boundary: avoid video-game assault skins or pure explosion staging.', risk: 'medium', tags: ['swat', 'breacher', 'urban'] },
  { id: 'sniper_spotter', name: '狙击观察手', nameEn: 'Sniper Spotter', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是把远处目标翻译成数字和呼吸节奏的狙击观察手。造型入口：望远镜、测距仪、伪装布、低声指令和长时间不动的脊背。母题：距离化杀伤的第二双眼。张力：他不扣扳机，却共同承担命中结果。视觉证据：脸侧压痕、地图笔记、草尘、压低肘部、耳麦细语和像石头一样等待的身体。边界：避免把他写成单独神枪手或炫耀枪械的人。', defEn: 'First read: a sniper spotter translating distant targets into numbers and breathing rhythm. Styling entry: binoculars, rangefinder, camouflage cloth, low instructions, and a back held still for hours. Motif: the second pair of eyes in distance violence. Tension: he does not pull the trigger yet shares the result of the shot. Visual evidence: cheek pressure marks, map notes, grass dust, lowered elbows, earpiece whisper, and a body waiting like stone. Boundary: avoid making him a lone marksman or weapon-display figure.', risk: 'medium', tags: ['sniper', 'spotter', 'camouflage'] },
  { id: 'counterterror_operator', name: '反恐突击队员', nameEn: 'Counterterror Operator', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是高度纪律化的反恐突击队员。造型入口：黑色战术服、耳麦、护目镜、短促手势和被训练压平的表情。母题：在公共空间里快速恢复秩序的专业身体。张力：危险越高，个人情绪越不能出现。视觉证据：贴身护甲、门廊阴影、手势通信、紧贴队友的站距、抬枪前的肩线和只露出眼睛的判断。边界：避免写成普通黑衣酷男或无任务逻辑的装备展示。', defEn: 'First read: a highly disciplined counterterror operator. Styling entry: black tactical uniform, headset, goggles, clipped signals, and expression flattened by training. Motif: a professional body restoring order fast inside public space. Tension: the higher the danger, the less personal emotion may appear. Visual evidence: close armor, corridor shadow, hand-signal communication, tight team spacing, shoulder line before raising the weapon, and judgment visible only in the eyes. Boundary: avoid generic black-clad cool figures or gear displays without mission logic.', risk: 'medium', tags: ['counterterror', 'operator', 'special'] },
  { id: 'combat_medic_operator', name: '战术医疗员', nameEn: 'Combat Medic Operator', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是在火线里携带救治流程的战术医疗员。造型入口：医疗臂章、止血带、剪刀、急救包和可以立刻跪下处理伤口的身体。母题：战斗系统里的照护接口。张力：他属于武装队伍，但视觉中心是稳定生命而不是输出暴力。视觉证据：红色医疗标识、手套、纱布包、战术背包分层、膝盖尘土和一边警戒一边按压的手。边界：避免写成普通医生或纯士兵。', defEn: 'First read: a combat medic carrying treatment workflow under fire. Styling entry: medical patch, tourniquet, shears, trauma pouch, and a body ready to kneel and treat injury instantly. Motif: the care interface inside a combat system. Tension: he belongs to an armed unit, but the visual center is life stabilization rather than violence output. Visual evidence: red medical mark, gloves, gauze packs, layered tactical bag, dusty knees, and hands applying pressure while staying alert. Boundary: avoid generic doctor or pure soldier treatment.', risk: 'medium', tags: ['combat_medic', 'operator', 'medical'] },
  { id: 'urban_undercover_agent', name: '城市卧底特勤', nameEn: 'Urban Undercover Agent', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是把普通人姿态训练成伪装的城市卧底特勤。造型入口：便装夹克、隐藏耳机、廉价购物袋或通勤包、街头观察眼。母题：行动能力被压进日常外壳。张力：越像路人，越需要让身体留下受训痕迹。视觉证据：过于稳定的站距、扫视橱窗反光、袖口里的通讯线、普通鞋底的快速磨损和不愿被注意的脸。边界：避免写成时尚路人或明牌间谍。', defEn: 'First read: an urban undercover agent whose ordinary posture is trained as disguise. Styling entry: plain jacket, hidden earpiece, cheap shopping bag or commuter pack, and street-observing eyes. Motif: operational ability compressed into daily appearance. Tension: the more civilian he looks, the more the trained body must quietly show. Visual evidence: too-stable spacing, scanning window reflections, communication wire in the cuff, fast wear on ordinary soles, and a face avoiding attention. Boundary: avoid fashionable pedestrians or obvious spy styling.', risk: 'medium', tags: ['undercover', 'agent', 'urban'] },
  { id: 'hostage_rescue_commander', name: '人质救援指挥官', nameEn: 'Hostage-Rescue Commander', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是把秒级判断压在脸上的人质救援指挥官。造型入口：战术地图、耳麦、标记笔、行动计时器和不离开现场屏幕的眼。母题：用指挥流程替别人承受生命重量。张力：他不一定冲在最前面，但所有人的进入时机都落在他的手势里。视觉证据：圈画路线、平板反光、半举起的手、压住情绪的嘴角、队员等待他的空间关系。边界：避免写成演说型领导或普通队长。', defEn: 'First read: a hostage-rescue commander carrying second-by-second judgment on the face. Styling entry: tactical map, headset, marker, action timer, and eyes fixed on live screens. Motif: bearing life-weight through command workflow. Tension: he may not enter first, but everyone’s timing sits inside his gesture. Visual evidence: circled routes, tablet glow, half-raised hand, mouth holding emotion down, and team members waiting in relation to him. Boundary: avoid speech-making leaders or generic squad captains.', risk: 'medium', tags: ['hostage_rescue', 'commander', 'tactical'] },
  { id: 'tactical_drone_pilot', name: '战术无人机操控员', nameEn: 'Tactical Drone Pilot', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是把战场视线外包给屏幕的战术无人机操控员。造型入口：控制器、屏幕背光、轻装背包、备用电池和长期盯屏造成的干眼神。母题：身体在地面，判断在空中。张力：暴力距离很远，但手指动作非常近、非常轻。视觉证据：拇指压杆、便携天线、地图叠层、脸上的冷屏光、膝上控制台和不看目标本体的凝视。边界：避免变成普通游戏玩家或全机械驾驶员。', defEn: 'First read: a tactical drone pilot outsourcing battlefield sight to screens. Styling entry: controller, screen glow, light pack, spare batteries, and dry eyes from long monitoring. Motif: body on the ground, judgment in the air. Tension: violence is distant while finger movement is close and light. Visual evidence: thumbs on sticks, portable antenna, map overlays, cold screen light on the face, lap console, and a gaze not looking at the target directly. Boundary: avoid generic gamer or full mechanical pilot.', ontologyLevel: 2, tags: ['drone', 'pilot', 'tactical'] },
  { id: 'near_future_riot_operator', name: '近未来防暴特勤', nameEn: 'Near-Future Riot Operator', group: 'A. 现代战术 / 佣兵 / 特勤', groupEn: 'A. Modern Tactical / Mercenary / Special Operations', def: '第一识别是被城市秩序系统技术化的近未来防暴特勤。造型入口：透明盾牌、非致命装备、面部识别护目镜、编号装甲和人群反光。母题：控制骚动而非赢得战斗的人。张力：装备越先进，身体越像制度接口。视觉证据：盾面划痕、冷光警示条、扩音器、压低重心、防暴队列间距和看向人群而非敌人的眼。边界：避免写成赛博战士或传统战场士兵。', defEn: 'First read: a near-future riot operator technologized by urban order systems. Styling entry: transparent shield, nonlethal gear, facial-recognition visor, numbered armor, and crowd reflections. Motif: someone controlling unrest rather than winning battle. Tension: the more advanced the gear, the more the body reads as an institutional interface. Visual evidence: scratched shield surface, cold warning strips, loudspeaker, lowered center of gravity, riot-line spacing, and eyes looking at a crowd rather than an enemy. Boundary: avoid cyber warriors or traditional battlefield soldiers.', ontologyLevel: 3, eras: futureEras, risk: 'medium', tags: ['riot', 'near_future', 'operator'] },

  { id: 'wandering_swordsman', name: '江湖游侠', nameEn: 'Wandering Wuxia Swordsman', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是没有固定门派归属的江湖游侠。造型入口：长剑、布衣、束发、旧斗笠和路途尘土。母题：用行走维持道义的人。张力：他看似自由，实际被旧恩怨、路见不平和身体训练牵引。视觉证据：磨损剑鞘、轻便包袱、草鞋尘、停在腰侧的手和随时离开的站姿。边界：避免仙侠漂浮特效或现代浪客。', defEn: 'First read: a wandering wuxia swordsman without fixed sect belonging. Styling entry: long sword, plain robe, tied hair, old bamboo hat, and road dust. Motif: someone maintaining moral pressure through travel. Tension: he appears free but is pulled by old debts, injustice, and trained reflexes. Visual evidence: worn scabbard, light bundle, dusty cloth shoes, hand near the waist, and a stance ready to leave. Boundary: avoid xianxia floating VFX or modern drifter styling.', eras: feudalEras, tags: ['wuxia', 'swordsman', 'wanderer'] },
  { id: 'cold_sword_maiden', name: '冷面女剑客', nameEn: 'Cold-Face Sword Maiden', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是情绪被剑术训练压低的冷面女剑客。造型入口：窄袖劲装、长剑、简洁发髻、冷淡眼和收住的步幅。母题：将年轻身体训练成锋利直线。张力：美感必须来自克制和反应速度，不是柔弱或摆拍。视觉证据：贴臂袖口、细剑穗、压平衣褶、下颌线紧、脚尖偏转和不解释自己的表情。边界：避免写成古风美人或性感女刺客。', defEn: 'First read: a cold-face sword maiden whose emotion is lowered by sword training. Styling entry: narrow sleeves, long sword, simple bun, cold gaze, and controlled step. Motif: a young body trained into a sharp line. Tension: beauty must come from restraint and reaction speed, not fragility or posing. Visual evidence: close sleeves, thin sword tassel, flattened folds, tight jawline, turned toe, and a face that explains nothing. Boundary: avoid generic period beauty or sexy assassin framing.', eras: feudalEras, tags: ['wuxia', 'sword_maiden', 'cold'] },
  { id: 'sect_senior_disciple', name: '门派大师兄', nameEn: 'Senior Sect Disciple', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是替门派秩序站在前排的门派大师兄。造型入口：统一门派服制、腰牌、整齐束发和规矩到近乎僵硬的站姿。母题：师承责任压出来的年轻权威。张力：他不是掌门，却已经承担照看同门和维持门规的重量。视觉证据：门派纹样、佩剑位置、袖口整洁、看向师弟妹的余光和被礼法收住的肩背。边界：避免写成普通热血少年或掌门人。', defEn: 'First read: a senior sect disciple standing at the front of sect order. Styling entry: unified sect clothing, waist token, neat tied hair, and a posture almost stiff with rules. Motif: young authority pressed out by lineage responsibility. Tension: he is not the master, yet already carries the weight of protecting juniors and maintaining discipline. Visual evidence: sect motifs, sword placement, clean cuffs, side glances toward juniors, and shoulders held by etiquette. Boundary: avoid generic hot-blooded youth or sect leader treatment.', eras: feudalEras, tags: ['sect', 'disciple', 'wuxia'] },
  { id: 'poison_hidden_weapon_master', name: '毒门暗器师', nameEn: 'Poison Hidden-Weapon Master', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是从不正面交锋的毒门暗器师。造型入口：袖中暗器、药瓶、黑色指套、窄袖和过分温和的微笑。母题：危险藏在手指、袖口和距离里。张力：他越像无害医者或文人，越需要让细节透出毒性。视觉证据：瓷瓶标签、指尖粉痕、袖口重量、避开正面的身法和看向对方脉门的眼。边界：避免大面积毒雾或怪物化毒体。', defEn: 'First read: a poison hidden-weapon master who avoids direct confrontation. Styling entry: sleeve weapons, medicine vials, black finger guards, narrow cuffs, and an overly gentle smile. Motif: danger hidden in fingers, cuffs, and distance. Tension: the more harmless he looks, the more the details must reveal poison. Visual evidence: porcelain vial labels, powder on fingertips, weighted cuffs, movement avoiding the front, and eyes watching the opponent’s pulse points. Boundary: avoid huge poison fog or monsterized toxic bodies.', ontologyLevel: 2, eras: feudalEras, risk: 'medium', tags: ['poison', 'hidden_weapon', 'wuxia'] },
  { id: 'bamboo_forest_assassin', name: '竹林刺客', nameEn: 'Bamboo-Forest Assassin', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是把身体藏进竹影节奏里的竹林刺客。造型入口：轻衣、短刃、竹叶擦痕、低姿态和贴近自然纹理的颜色。母题：环境本身成为掩护。张力：杀意要轻，轻到像风声而不是正面威胁。视觉证据：衣摆竹叶屑、手腕短刀、弯低背线、半侧脸和随竹竿间隙移动的脚。边界：避免忍者套装化或大场景打斗。', defEn: 'First read: a bamboo-forest assassin hiding the body inside bamboo-shadow rhythm. Styling entry: light clothing, short blade, bamboo-leaf scratches, low posture, and colors close to natural texture. Motif: environment itself becomes cover. Tension: killing intent should be light, like wind rather than frontal threat. Visual evidence: leaf bits on hem, wrist blade, bent back line, half-turned face, and feet moving through bamboo gaps. Boundary: avoid ninja costume clichés or large fight scenes.', eras: feudalEras, risk: 'medium', tags: ['assassin', 'bamboo', 'wuxia'] },
  { id: 'beggar_sect_master', name: '丐帮高手', nameEn: 'Beggar-Sect Master', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是把落魄外表当成江湖伪装的丐帮高手。造型入口：破衣、竹杖、酒葫芦、松散发髻和坐卧都能发力的身体。母题：低身份外壳里的高武力。张力：贫穷痕迹不能变成可怜，必须显出自在和压不住的底气。视觉证据：补丁层次、杖头磨损、酒渍、歪坐重心、笑里藏着判断的眼。边界：避免滑稽乞丐或干净侠客。', defEn: 'First read: a beggar-sect master using destitution as jianghu disguise. Styling entry: ragged clothes, bamboo staff, wine gourd, loose hair, and a body that can strike from sitting or lying. Motif: high martial ability inside a low-status shell. Tension: poverty marks must not become pity; they should show ease and hidden confidence. Visual evidence: layered patches, worn staff tip, wine stains, tilted sitting weight, and eyes judging behind a smile. Boundary: avoid comic beggar or clean heroic swordsman.', eras: feudalEras, tags: ['beggar_sect', 'master', 'wuxia'] },
  { id: 'imperial_guard_swordsman', name: '御前带刀侍卫', nameEn: 'Imperial Guard Swordsman', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是皇权近侧的御前带刀侍卫。造型入口：宫廷护卫服、佩刀、腰牌、挺直脊背和不越礼制的警戒距离。母题：把个人武艺交给皇权门口的人。张力：危险必须被礼法压住，不能像江湖浪人那样自由。视觉证据：宫门站位、刀鞘反光、规整衣层、低头行礼后的抬眼和始终护住通道的身体角度。边界：避免泛古装美男或普通皇宫士兵。', defEn: 'First read: an imperial guard swordsman stationed close to sovereign power. Styling entry: court guard clothing, side sword, waist token, straight back, and alert distance that never breaks etiquette. Motif: personal skill handed over to the palace threshold. Tension: danger must be pressed under ritual order, not wander like jianghu freedom. Visual evidence: palace-gate placement, scabbard reflection, ordered layers, eyes lifting after a bow, and body angle always protecting passage. Boundary: avoid generic period pretty men or ordinary palace soldiers.', eras: feudalEras, tags: ['imperial_guard', 'swordsman', 'court'] },
  { id: 'shaolin_monk_fighter', name: '少林武僧', nameEn: 'Shaolin Warrior Monk', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是把戒律练进肌肉记忆的少林武僧。造型入口：僧衣、念珠、长棍、剃发和稳定下盘。母题：修行与战斗共用同一套身体纪律。张力：力量必须朴素、节制，不靠夸张怒火。视觉证据：磨旧布鞋、棍身油光、合掌后的转身、肩背厚度、呼吸稳定和不炫耀武力的脸。边界：避免超级英雄僧人或浮夸法术。', defEn: 'First read: a Shaolin warrior monk with discipline trained into muscle memory. Styling entry: monk robe, prayer beads, staff, shaved head, and stable lower stance. Motif: practice and combat sharing the same body discipline. Tension: power must stay plain and restrained, not driven by exaggerated rage. Visual evidence: worn cloth shoes, polished staff, turn after pressed palms, thick shoulders and back, steady breath, and a face not showing off force. Boundary: avoid superhero monk or flashy magic.', ontologyLevel: 2, eras: feudalEras, tags: ['shaolin', 'monk', 'fighter'] },
  { id: 'demonic_cult_saintess', name: '魔教圣女', nameEn: 'Demonic-Cult Saintess', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是被正邪叙事推到中心的魔教圣女。造型入口：黑红衣饰、面纱、铃铛、冷艳表情和不完全暴露的门派符号。母题：危险魅力与宗派政治绑定。张力：她不是单纯妖艳，而是被组织需要、江湖恐惧和个人意志同时塑形。视觉证据：腰间铃声、半遮面部、红线刺绣、站在人群后仍被看见的姿态和像命令又像试探的眼。边界：避免写成性感反派或仙侠魔女。', defEn: 'First read: a demonic-cult saintess pushed to the center by righteous/evil narratives. Styling entry: black-red clothing, veil, bells, cold beauty, and partially concealed sect signs. Motif: dangerous allure bound to sect politics. Tension: she is not merely seductive; organization need, jianghu fear, and personal will shape her together. Visual evidence: bell at the waist, half-covered face, red-thread embroidery, a posture visible even behind others, and eyes that feel both command and test. Boundary: avoid sexy villain or xianxia witch treatment.', ontologyLevel: 3, eras: feudalEras, risk: 'medium', tags: ['demonic_cult', 'saintess', 'wuxia'] },
  { id: 'retired_jianghu_innkeeper', name: '退隐江湖客栈老板', nameEn: 'Retired Jianghu Innkeeper', group: 'B. 武侠 / 门派 / 江湖', groupEn: 'B. Wuxia / Sect / Jianghu', def: '第一识别是把江湖杀气藏进算盘和茶水里的退隐客栈老板。造型入口：粗布衣、算盘、旧剑藏匣、温和表情和随手擦桌的动作。母题：退隐后的武力残留。张力：他看似只经营生意，但身体永远知道门口来了什么人。视觉证据：柜台阴影、藏剑木匣、手指老茧、突然安静的笑和站在出入口侧面的习惯。边界：避免普通老板或重新冲回战场的英雄。', defEn: 'First read: a retired jianghu innkeeper hiding killing skill inside abacus and tea service. Styling entry: coarse robe, abacus, old sword box, gentle expression, and casual table-wiping movement. Motif: martial residue after withdrawal. Tension: he appears to run a business, yet the body always knows who has entered. Visual evidence: counter shadow, hidden sword case, finger calluses, smile going suddenly quiet, and habit of standing beside exits. Boundary: avoid generic shopkeeper or hero returning to the battlefield.', eras: feudalEras, tags: ['retired', 'innkeeper', 'jianghu'] },

  { id: 'ronin', name: '浪人', nameEn: 'Ronin', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是失去主君后仍被武士礼法缠住的浪人。造型入口：旧和服、刀、旅尘、低头行走和不再崭新的发髻。母题：自由与羞耻同时压在身体上。张力：他没有组织，却不能完全脱离过去的等级习惯。视觉证据：磨损刀鞘、衣襟风尘、避开人群的眼、手离刀太近和像随时准备离开的肩背。边界：避免写成潇洒旅行侠客或西部枪手。', defEn: 'First read: a ronin still bound by samurai etiquette after losing his lord. Styling entry: old kimono, sword, travel dust, lowered walk, and a hair knot no longer pristine. Motif: freedom and shame pressing on the same body. Tension: he has no organization, yet cannot fully leave old hierarchy habits. Visual evidence: worn scabbard, dusty collar, eyes avoiding crowds, hand too close to the sword, and shoulders ready to leave. Boundary: avoid carefree traveler swordsman or western gunfighter treatment.', eras: feudalEras, tags: ['ronin', 'samurai', 'wanderer'] },
  { id: 'samurai_retainer', name: '武士家臣', nameEn: 'Samurai Retainer', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是被家纹和主从秩序固定住的武士家臣。造型入口：家纹、甲胄层次、刀、跪坐礼法和挺直得不自然的背。母题：个人武力被忠诚制度收编。张力：他不是自由战士，每一处装备都指向某个家名。视觉证据：家纹位置、刀的朝向、护甲系带、白布维护痕、低头等命令的姿态和不越线的视线。边界：避免泛武侠或西幻骑士化。', defEn: 'First read: a samurai retainer fixed by clan crest and lord-vassal order. Styling entry: clan marks, layered armor, sword, kneeling etiquette, and an unnaturally straight back. Motif: personal violence absorbed by loyalty systems. Tension: he is not a free fighter; every piece of gear points to a house name. Visual evidence: crest placement, sword direction, armor ties, white-cloth maintenance marks, posture waiting for command, and gaze that does not cross boundaries. Boundary: avoid generic wuxia or western-fantasy knight treatment.', eras: feudalEras, tags: ['samurai', 'retainer', 'clan'] },
  { id: 'onna_musha', name: '女武者', nameEn: 'Onna-Musha', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是礼法内部拥有战斗权限的女武者。造型入口：薙刀、束发、护甲裙摆、冷静面部和稳定手腕。母题：被家族、宅邸和战事共同要求的女性战斗身体。张力：她不能只显得美或勇，要显出长期训练和被礼法观看的克制。视觉证据：薙刀握距、裙甲层次、束发绳、微微下沉的站姿和没有求助感的眼。边界：避免女战士Cos或柔弱贵族小姐。', defEn: 'First read: an onna-musha with combat authority inside etiquette. Styling entry: naginata, tied hair, armor skirt, calm face, and stable wrists. Motif: a female combat body required by family, household, and war. Tension: she cannot simply look beautiful or brave; she must show training under etiquette’s gaze. Visual evidence: naginata grip spacing, skirt-armor layers, hair cord, slightly lowered stance, and eyes without appeal for help. Boundary: avoid female warrior cosplay or fragile noblewoman tropes.', eras: feudalEras, tags: ['onna_musha', 'naginata', 'samurai'] },
  { id: 'ninja_courier', name: '忍者信使', nameEn: 'Ninja Courier', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是把速度和保密当成身份的忍者信使。造型入口：深色轻装、卷轴、绑腿、短外套和贴地移动的低姿态。母题：信息比武器更危险。张力：他不是炫技刺客，身体价值在于能把消息完整带到。视觉证据：封蜡卷轴、防水布包、鞋底磨损、半蹲等待、避光侧脸和随时转向的脚尖。边界：避免全黑漫画忍者或杀戮主角。', defEn: 'First read: a ninja courier whose identity is speed and secrecy. Styling entry: dark light gear, scroll, leg wraps, short jacket, and low movement close to the ground. Motif: information more dangerous than weapons. Tension: he is not a flashy assassin; the body’s value is delivering the message intact. Visual evidence: wax-sealed scroll, waterproof pouch, worn soles, half-crouched waiting, face kept out of light, and toes ready to turn. Boundary: avoid all-black comic ninja or killing-protagonist framing.', eras: feudalEras, tags: ['ninja', 'courier', 'stealth'] },
  { id: 'ashigaru_foot_soldier', name: '足轻步兵', nameEn: 'Ashigaru Foot Soldier', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是战争底层被临时武装起来的足轻步兵。造型入口：简易甲、长枪、草鞋、疲惫站姿和被队列磨出来的身体。母题：大名战争里最低成本的军事身体。张力：他不是英雄，而是被制度推到前线的普通人。视觉证据：粗绳系甲、泥点、握枪手茧、歪斜头盔、跟随队列的视线和想保持体面的紧张。边界：避免威风武士或无脸杂兵。', defEn: 'First read: an ashigaru foot soldier, a lower-class body temporarily armed by war. Styling entry: simple armor, spear, straw sandals, tired stance, and a body shaped by formation. Motif: the lowest-cost military body in daimyo warfare. Tension: he is not a hero but an ordinary person pushed forward by institution. Visual evidence: rough armor cords, mud spots, spear-hand calluses, tilted helmet, eyes following the line, and tense effort to keep dignity. Boundary: avoid imposing samurai or faceless extras.', eras: feudalEras, tags: ['ashigaru', 'foot_soldier', 'spear'] },
  { id: 'kendo_dojo_master', name: '剑道馆师范', nameEn: 'Kendo Dojo Master', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是把武士礼法现代化为道场训练的剑道馆师范。造型入口：剑道服、竹刀、护具、跪坐姿态和安静到严厉的表情。母题：战斗被转化成教育、重复和礼节。张力：他不需要实战血气，压迫力来自规矩和身体控制。视觉证据：竹刀握痕、护具磨损、道场木地板、坐姿轴线、纠正学生时极小的手势。边界：避免古代武士或体育教练平面化。', defEn: 'First read: a kendo dojo master modernizing samurai etiquette into training. Styling entry: kendo uniform, bamboo sword, armor, seiza posture, and a quiet severe expression. Motif: combat transformed into education, repetition, and manners. Tension: he needs no battlefield heat; pressure comes from rules and body control. Visual evidence: shinai grip wear, marked armor, dojo wood floor, seated axis, and tiny hand gestures correcting students. Boundary: avoid ancient samurai or flat sports-coach treatment.', eras: ['modern', 'contemporary'], tags: ['kendo', 'dojo', 'master'] },
  { id: 'yakuza_swordsman', name: '极道刀客', nameEn: 'Yakuza Swordsman', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是现代黑帮身体里残留古典武士姿态的极道刀客。造型入口：西装、纹身边缘、短刀、夜街和过分礼貌的站距。母题：义理被城市暴力重新包装。张力：他不是古代武士复活，而是在现代地下秩序里表演旧式尊严。视觉证据：衬衫下纹身露边、刀袋、夜店后门、整理袖口、低声道歉前的危险沉默。边界：避免写成普通黑帮打手或赛博武士。', defEn: 'First read: a yakuza swordsman carrying classical samurai residue inside a modern gang body. Styling entry: suit, tattoo edges, short blade, night street, and excessively polite spacing. Motif: obligation repackaged by urban violence. Tension: he is not an ancient samurai reborn, but performs old-style dignity inside modern underground order. Visual evidence: tattoo edges under shirt, blade pouch, nightclub back door, adjusted cuffs, and dangerous silence before a low apology. Boundary: avoid generic gang enforcer or cyber samurai treatment.', eras: industrialModernEras, risk: 'medium', tags: ['yakuza', 'swordsman', 'gang'] },
  { id: 'imperial_palace_guard', name: '皇宫近卫', nameEn: 'Imperial Palace Guard', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是宫门礼制和暴力职责重合的皇宫近卫。造型入口：仪仗服、长柄武器、宫门站姿、白布细节和被规定好的距离。母题：把危险摆成秩序景观。张力：他必须像装饰一样静止，却随时能转为护卫力量。视觉证据：长柄武器垂直线、衣摆对称、宫门阴影、白手套、抬眼瞬间和不离岗位的脚。边界：避免普通仪仗队或幻想骑士。', defEn: 'First read: an imperial palace guard where court ceremony overlaps violent duty. Styling entry: ceremonial guard dress, polearm, palace-gate stance, white-cloth details, and prescribed distance. Motif: danger arranged as an order spectacle. Tension: he must stand like decoration while remaining able to become guard force instantly. Visual evidence: vertical polearm line, symmetrical hem, gate shadow, white gloves, sudden eye lift, and feet never leaving the post. Boundary: avoid generic parade guard or fantasy knight treatment.', eras: feudalEras, tags: ['palace_guard', 'imperial', 'ritual'] },
  { id: 'sword_polisher', name: '刀剑研磨师', nameEn: 'Sword Polisher', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是通过手艺维护杀器尊严的刀剑研磨师。造型入口：白布、磨石、刀身反光、安静手部和不沾血的职业距离。母题：暴力的维护者而非执行者。张力：他不战斗，却比任何人都清楚刀的身份和历史。视觉证据：布面油痕、磨石水光、刀刃映脸、低头检查角度、干净袖口和过分慎重的呼吸。边界：避免写成铁匠或剑客。', defEn: 'First read: a sword polisher maintaining the dignity of killing tools through craft. Styling entry: white cloth, whetstone, blade reflection, quiet hands, and professional distance from blood. Motif: maintainer of violence rather than executor. Tension: he does not fight, yet knows the blade’s identity and history more than anyone. Visual evidence: oil marks on cloth, wet stone shine, face reflected in blade, lowered angle-checking gaze, clean cuffs, and overly careful breath. Boundary: avoid blacksmith or swordsman treatment.', eras: feudalEras, tags: ['sword_polisher', 'craft', 'blade'] },
  { id: 'cyber_samurai_retainer', name: '赛博武士家臣', nameEn: 'Cyber Samurai Retainer', group: 'C. 武士 / 家臣 / 东亚战斗礼法', groupEn: 'C. Samurai / Retainer / East Asian Martial Etiquette', def: '第一识别是把封建忠诚转译成企业协议的赛博武士家臣。造型入口：电子家纹、合成甲片、能量刀鞘、协议灯条和过于端正的未来站姿。母题：旧式主从关系进入数据化组织。张力：未来装备不能冲散礼法；技术只是让忠诚变得可追踪。视觉证据：发光家徽、访问权限牌、刀鞘接口、面罩下的低头礼、机械但守礼的手。边界：避免随机霓虹武士或完整机甲人。', defEn: 'First read: a cyber samurai retainer translating feudal loyalty into corporate protocol. Styling entry: electronic crest, synthetic armor plates, energy scabbard, protocol light strips, and an overly formal future stance. Motif: old lord-vassal relation entering data organizations. Tension: future equipment must not dissolve etiquette; technology only makes loyalty trackable. Visual evidence: glowing clan mark, access badge, scabbard interface, bow under visor, and mechanical yet polite hands. Boundary: avoid random neon samurai or full mecha person.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['cyber_samurai', 'retainer', 'future'] },

  { id: 'black_suit_hitman', name: '黑西装杀手', nameEn: 'Black-Suit Hitman', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是把死亡做成冷静服务的黑西装杀手。造型入口：黑色西装、隐藏武器、夜间交通、干净袖口和无表情的等待。母题：职业化的不可见暴力。张力：他必须像普通商务人一样干净，同时让姿态透露不可协商。视觉证据：内袋轮廓、皮鞋反光、旧车后座、手套、看表动作和不解释目标的眼。边界：避免黑帮大片海报或血腥猎奇。', defEn: 'First read: a black-suit hitman turning death into calm service. Styling entry: black suit, hidden weapon, night transport, clean cuffs, and expressionless waiting. Motif: professional invisible violence. Tension: he must look as clean as a businessperson while posture reveals no negotiation. Visual evidence: inner-pocket contour, polished shoes, old car back seat, gloves, checking a watch, and eyes that do not explain the target. Boundary: avoid gangster-poster spectacle or gore fascination.', eras: industrialModernEras, risk: 'medium', tags: ['hitman', 'black_suit', 'urban'] },
  { id: 'mafia_enforcer', name: '黑手党打手', nameEn: 'Mafia Enforcer', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是替家族秩序把话说到最后的黑手党打手。造型入口：厚西装、金戒指、旧伤、餐馆后门和不急着动手的站姿。母题：亲族、债务和暴力服务绑定。张力：他不需要夸张凶狠，压力来自熟悉场所里突然变硬的礼貌。视觉证据：油亮领口、粗手、包间门缝、戒指敲桌、半遮伤痕和笑容消失前的停顿。边界：避免普通恶棍或纯肌肉保镖。', defEn: 'First read: a mafia enforcer who speaks the final line for family order. Styling entry: heavy suit, gold ring, old scars, restaurant back door, and a stance not rushing to act. Motif: kinship, debt, and violence service bound together. Tension: he needs no exaggerated menace; pressure comes from politeness hardening in familiar places. Visual evidence: shiny collar, rough hands, private-room doorway, ring tapping the table, half-hidden scars, and the pause before the smile disappears. Boundary: avoid generic thug or pure muscle bodyguard.', eras: industrialModernEras, risk: 'medium', tags: ['mafia', 'enforcer', 'family'] },
  { id: 'triad_red_pole', name: '洪门红棍', nameEn: 'Triad Red Pole', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是堂口秩序里的武力执行者洪门红棍。造型入口：唐装或西装、纹身、短棍或刀、堂口符号和街区站位。母题：地方帮会把暴力制度化为职位。张力：他不是随机街头斗士，而是带着等级、仪式和地盘边界行动。视觉证据：胸口暗纹、袖口露纹身、棍袋、茶楼或巷口位置、招呼兄弟的手势和看守一段街的身体角度。边界：避免写成泛黑帮或古装侠客。', defEn: 'First read: a Triad Red Pole, force executor inside lodge order. Styling entry: tang jacket or suit, tattoos, baton or blade, lodge symbols, and block placement. Motif: local gang systems turning violence into rank. Tension: he is not a random street fighter; he acts with hierarchy, ritual, and territory boundaries. Visual evidence: hidden chest motif, tattoo edge at cuff, baton pouch, teahouse or alley position, gesture greeting brothers, and body angle guarding a section of street. Boundary: avoid generic gangster or period swordsman treatment.', eras: industrialModernEras, risk: 'medium', tags: ['triad', 'red_pole', 'gang'] },
  { id: 'female_contract_killer', name: '女性契约杀手', nameEn: 'Female Contract Killer', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是把个人魅力降到最低的女性契约杀手。造型入口：简洁外套、手套、短发、干净武器和便于离开的鞋。母题：不解释动机的专业冷感。张力：她可以有吸引力，但吸引力不能成为任务逻辑；真正的力量在于无多余动作。视觉证据：平整袖口、一次性手机、空白表情、固定目标的眼、擦干净的工具和避开社交距离的站位。边界：避免性感杀手模板或复仇故事主角化。', defEn: 'First read: a female contract killer who lowers personal allure to a minimum. Styling entry: clean coat, gloves, short hair, tidy weapon, and shoes made for leaving. Motif: professional coldness without motive explanation. Tension: she may be attractive, but attraction cannot be the mission logic; power sits in the absence of extra movement. Visual evidence: flat cuffs, disposable phone, blank expression, eyes fixed on target, cleaned tools, and stance avoiding social distance. Boundary: avoid sexy assassin templates or revenge-protagonist framing.', risk: 'medium', tags: ['contract_killer', 'female', 'professional'] },
  { id: 'getaway_driver', name: '逃亡车手', nameEn: 'Getaway Driver', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是把路线、时间和风险握在方向盘上的逃亡车手。造型入口：驾驶手套、旧夹克、车钥匙、后视镜眼神和坐得很低的身体。母题：速度作为犯罪流程里的边界技术。张力：他不是赛车手，真正的压力来自等待、转弯和不问乘客发生了什么。视觉证据：磨损方向盘、夜色仪表盘、半拉拉链、听车声的侧脸、后视镜里的警觉眼和随时发动的手。边界：避免炫车广告或动作片飞车英雄。', defEn: 'First read: a getaway driver holding route, time, and risk on the steering wheel. Styling entry: driving gloves, old jacket, car keys, rearview gaze, and a body seated low. Motif: speed as boundary technique inside crime workflow. Tension: he is not a racer; pressure comes from waiting, turning, and not asking what passengers did. Visual evidence: worn steering wheel, night dashboard, half-zipped jacket, profile listening to the engine, alert eyes in the mirror, and hands ready to start. Boundary: avoid car-ad glamour or action-film stunt hero.', risk: 'medium', tags: ['driver', 'getaway', 'crime'] },
  { id: 'nightclub_bodyguard', name: '夜店保镖', nameEn: 'Nightclub Bodyguard', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是站在消费娱乐边界上的夜店保镖。造型入口：黑西装、耳机、门口站姿、粗手和对人群流速的判断。母题：用肉身维持夜生活秩序。张力：他既是服务业员工，也是门槛权力本身。视觉证据：门口灯光、腕带检查、耳机线、手掌挡人、低头听指令和扫视醉客的眼。边界：避免普通黑帮打手或健身模特。', defEn: 'First read: a nightclub bodyguard standing at the boundary of consumption and entertainment. Styling entry: black suit, earpiece, doorway stance, rough hands, and judgment of crowd flow. Motif: bodily power maintaining nightlife order. Tension: he is both service worker and threshold authority. Visual evidence: door light, wristband check, earpiece wire, palm stopping someone, lowered head receiving instructions, and eyes scanning drunk customers. Boundary: avoid generic gang thug or fitness model treatment.', risk: 'medium', tags: ['bodyguard', 'nightclub', 'security'] },
  { id: 'street_gang_lieutenant', name: '街头帮派副手', nameEn: 'Street-Gang Lieutenant', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是替街区老大处理日常秩序的帮派副手。造型入口：帮派色、项链、街角站位、短促手势和地方熟人网络。母题：地方性暴力的中层管理。张力：他不是最高权力，但每个人都知道他能传话、施压、收账。视觉证据：固定街角、手机消息、手势暗号、鞋底停在边界线上、看似闲聊却在巡视的眼。边界：避免无组织街头混混或纯说唱造型。', defEn: 'First read: a street-gang lieutenant handling daily order for the block leader. Styling entry: gang colors, chain, corner position, clipped gestures, and local acquaintance networks. Motif: middle management of local violence. Tension: he is not the highest power, but everyone knows he can carry messages, apply pressure, and collect. Visual evidence: fixed corner, phone messages, hand signs, soles stopping on a boundary line, and eyes patrolling while pretending to chat. Boundary: avoid disorganized street kids or pure rapper styling.', risk: 'medium', tags: ['street_gang', 'lieutenant', 'block'] },
  { id: 'casino_debt_collector', name: '赌场讨债人', nameEn: 'Casino Debt Collector', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是把债务变成身体压力的赌场讨债人。造型入口：亮面西装、账本、筹码、冷笑和过分耐心的等待。母题：金钱关系滑向人身威胁。张力：他不必立刻动粗，真正危险在于知道对方欠了多少、住在哪里。视觉证据：账页折角、筹码指尖、包间暗灯、贴近但不碰人的站距、慢慢收起笑的脸。边界：避免普通赌场荷官或夸张反派。', defEn: 'First read: a casino debt collector turning debt into bodily pressure. Styling entry: glossy suit, ledger, chips, dry smile, and overly patient waiting. Motif: money relation sliding into personal threat. Tension: he need not act violently at once; danger lies in knowing how much the person owes and where they live. Visual evidence: folded ledger pages, chips at fingertips, private-room dim light, standing close without touching, and a face slowly putting away the smile. Boundary: avoid casino dealer or exaggerated villain treatment.', risk: 'medium', tags: ['casino', 'debt_collector', 'gang'] },
  { id: 'noir_femme_fatale_assassin', name: '黑色电影蛇蝎杀手', nameEn: 'Noir Femme-Fatale Assassin', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是把欲望伪装成任务入口的黑色电影蛇蝎杀手。造型入口：黑裙、红唇、短刀或小型手枪、烟雾和斜侧光。母题：观看关系里的危险交易。张力：她不是单纯诱惑，而是在镜头、谎言和死亡委托之间保持主动权。视觉证据：手套、香烟灰、包内金属轮廓、半转身的眼神、冷静微笑和让对方误判距离的姿态。边界：避免色情化或普通复古女郎。', defEn: 'First read: a noir femme-fatale assassin using desire as the entry point for a task. Styling entry: black dress, red lips, small blade or pistol, smoke, and oblique side light. Motif: dangerous transaction inside the act of looking. Tension: she is not mere seduction; she keeps initiative between camera, lies, and death contract. Visual evidence: gloves, cigarette ash, metal contour inside handbag, half-turned gaze, calm smile, and posture that makes others misread distance. Boundary: avoid eroticization or generic vintage girl treatment.', risk: 'medium', tags: ['noir', 'femme_fatale', 'assassin'] },
  { id: 'cyber_yakuza_enforcer', name: '赛博极道执行者', nameEn: 'Cyber Yakuza Enforcer', group: 'D. 黑帮 / 杀手 / 城市暴力', groupEn: 'D. Gang / Assassin / Urban Violence', def: '第一识别是把帮派义理转译成数据协议的赛博极道执行者。造型入口：电子纹身、合成西装、义体手臂、加密身份牌和冷光街区。母题：地下秩序在未来城市里被接口化。张力：技术不能让他变成普通赛博战士，核心仍是堂口、债务和面子。视觉证据：发光纹身沿袖口露出、义体指节、数据令牌、夜店后巷、低头鞠躬后的威胁眼。边界：避免随机霓虹机甲或无组织黑客。', defEn: 'First read: a cyber yakuza enforcer translating gang obligation into data protocol. Styling entry: electronic tattoos, synthetic suit, prosthetic arm, encrypted identity tag, and cold-lit blocks. Motif: underground order made interface-based in a future city. Tension: technology must not make him a generic cyber warrior; the core remains lodge, debt, and face. Visual evidence: glowing tattoo at cuff, prosthetic knuckles, data token, nightclub back alley, and threatening eyes after a bow. Boundary: avoid random neon mecha or organizationless hacker styling.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['cyber_yakuza', 'enforcer', 'future'] },

  { id: 'court_shadow_agent', name: '宫廷密探', nameEn: 'Court Shadow Agent', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是把危险藏在礼制衣层里的宫廷密探。造型入口：礼制外观、袖中暗器、腰牌、窄门廊等待和克制眼神。母题：暴力通过信息和礼仪发生。张力：他越像普通侍从，越要让袖口、视线和站位透露任务。视觉证据：暗袋、密信折痕、腰牌反光、低声汇报、半步退后的姿态和不直接看人的眼。边界：避免大场面刺杀或普通宫廷美人。', defEn: 'First read: a court shadow agent hiding danger inside ritual dress layers. Styling entry: ceremonial appearance, sleeve weapons, waist token, narrow-corridor waiting, and restrained eyes. Motif: violence happening through information and etiquette. Tension: the more he resembles an attendant, the more cuffs, gaze, and placement must reveal the mission. Visual evidence: hidden pocket, folded secret letter, waist-token shine, low report, half-step backward posture, and eyes that do not look directly. Boundary: avoid large assassination scenes or generic court beauty.', eras: feudalEras, risk: 'medium', tags: ['court', 'spy', 'shadow'] },
  { id: 'imperial_secret_police', name: '帝国秘密警察', nameEn: 'Imperial Secret Police', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是替君主观看所有人的帝国秘密警察。造型入口：深色官服、令牌、审讯记录、窄袖和文件压出的冷脸。母题：国家权力进入私人恐惧。张力：他不需要公开暴力，记录、传唤和沉默已经足够压迫。视觉证据：封口档案、令牌边缘、墨迹手指、门外等待、问话时停顿过长的眼。边界：避免普通侦探或大反派夸张化。', defEn: 'First read: imperial secret police watching everyone on behalf of the ruler. Styling entry: dark official uniform, token, interrogation records, narrow sleeves, and a cold face pressed by files. Motif: state power entering private fear. Tension: he needs no open violence; records, summons, and silence already pressure enough. Visual evidence: sealed files, token edge, ink-stained fingers, waiting outside doors, and eyes pausing too long during questions. Boundary: avoid generic detective or exaggerated villain treatment.', eras: feudalEras, risk: 'medium', tags: ['secret_police', 'imperial', 'spy'] },
  { id: 'royal_poisoner', name: '王室毒师', nameEn: 'Royal Poisoner', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是把杀意放进宴会流程的王室毒师。造型入口：小药瓶、细手套、礼服袖口、低声谈话和永远干净的指尖。母题：宫廷亲密关系里的隐形死亡。张力：他必须像医师、侍酒人或顾问一样可信。视觉证据：瓶塞蜡印、银勺、酒杯边缘、袖口内袋、观察吞咽的眼和不留下痕迹的手。边界：避免毒雾魔法或外露怪异毒体。', defEn: 'First read: a royal poisoner placing murder inside banquet workflow. Styling entry: tiny vials, fine gloves, formal cuffs, low conversation, and fingertips always clean. Motif: invisible death inside court intimacy. Tension: he must appear as credible as a physician, wine servant, or advisor. Visual evidence: waxed vial stoppers, silver spoon, goblet edge, inner cuff pocket, eyes watching swallowing, and hands leaving no trace. Boundary: avoid poison-cloud magic or exposed monstrous toxic bodies.', eras: feudalEras, risk: 'medium', tags: ['poisoner', 'royal', 'court'] },
  { id: 'diplomatic_spy', name: '外交间谍', nameEn: 'Diplomatic Spy', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是把外语、礼服和微笑变成情报工具的外交间谍。造型入口：礼服、密信、翻译手册、酒会胸牌和不露痕迹的社交站位。母题：宴会里的国家边界移动。张力：她越优雅，越要显出正在筛选信息、记住人名和隐藏立场。视觉证据：折叠便条、手套捏杯脚、耳语距离、双语文件、礼貌微笑下不笑的眼。边界：避免普通外交官或艳谍模板。', defEn: 'First read: a diplomatic spy turning languages, formalwear, and smile into intelligence tools. Styling entry: formalwear, secret letters, translation notes, reception badge, and social placement without traces. Motif: national borders moving inside a banquet. Tension: the more elegant she is, the more she must read as filtering information, remembering names, and hiding position. Visual evidence: folded note, gloved hand on glass stem, whisper distance, bilingual papers, and eyes not smiling under a polite smile. Boundary: avoid generic diplomat or seductive-spy template.', eras: ['early_modern', 'industrial', 'modern'], risk: 'medium', tags: ['diplomatic', 'spy', 'intelligence'] },
  { id: 'palace_eunuch_informant', name: '宫廷内侍情报人', nameEn: 'Palace Eunuch Informant', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是因低姿态而能听见所有秘密的宫廷内侍情报人。造型入口：内侍服、拂尘、低头姿态、软底鞋和熟悉宫内路线的脚步。母题：被忽视的位置变成情报权力。张力：他看似无害服务者，却掌握流言、寝宫动线和谁害怕谁。视觉证据：拂尘柄、袖中纸条、回廊阴影、半弯背、只在无人时抬起的眼。边界：避免喜剧化太监形象或普通仆人。', defEn: 'First read: a palace eunuch informant who hears everything because of a lowered posture. Styling entry: attendant dress, whisk, lowered body, soft shoes, and steps familiar with palace routes. Motif: an ignored position becoming intelligence power. Tension: he appears harmless, yet knows gossip, chamber routes, and who fears whom. Visual evidence: whisk handle, paper hidden in sleeve, corridor shadow, half-bent back, and eyes lifting only when nobody watches. Boundary: avoid comic eunuch stereotypes or generic servant treatment.', eras: feudalEras, risk: 'medium', tags: ['palace', 'informant', 'court'] },
  { id: 'cipher_clerk_spy', name: '密码文书间谍', nameEn: 'Cipher-Clerk Spy', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是把文字前线化的密码文书间谍。造型入口：密电纸、眼镜、灰色制服、文件夹和长时间坐姿。母题：战争藏在表格、代码和抄写错误里。张力：他看似文弱，真正危险是能让一句话抵达或消失。视觉证据：打字机或终端、铅笔痕、烧毁纸角、疲惫眼、袖口墨迹和听见门响时停住的手。边界：避免战场士兵或普通办公室职员。', defEn: 'First read: a cipher-clerk spy turning text into a front line. Styling entry: cipher papers, glasses, grey uniform, folders, and long seated posture. Motif: war hidden in forms, code, and transcription errors. Tension: he appears frail, but danger lies in making a sentence arrive or vanish. Visual evidence: typewriter or terminal, pencil marks, burned paper edge, tired eyes, inked cuffs, and hands freezing when the door opens. Boundary: avoid battlefield soldier or generic office clerk treatment.', eras: ['industrial', 'modern', 'contemporary'], tags: ['cipher', 'clerk', 'spy'] },
  { id: 'resistance_messenger', name: '抵抗组织信使', nameEn: 'Resistance Messenger', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是把日常路线变成秘密通道的抵抗组织信使。造型入口：旧外套、藏信、快速步伐、紧张眼神和看似普通的布包。母题：城市生活表面下的反抗物流。张力：她不是战士，却可能因为一张纸改变整条街的命运。视觉证据：鞋底磨损、缝进衣里的纸条、路口停顿、假装买东西的手和听见巡逻声时变硬的脸。边界：避免英雄冲锋或完整谍战剧情。', defEn: 'First read: a resistance messenger turning daily routes into secret passages. Styling entry: old coat, hidden letter, fast steps, tense gaze, and an ordinary cloth bag. Motif: resistance logistics beneath urban daily life. Tension: she is not a fighter, yet one paper may change the fate of a street. Visual evidence: worn soles, paper sewn into clothing, pause at intersections, hand pretending to shop, and face hardening at patrol sounds. Boundary: avoid heroic charges or full spy-thriller plotting.', eras: ['industrial', 'modern', 'contemporary'], risk: 'medium', tags: ['resistance', 'messenger', 'spy'] },
  { id: 'courtesan_informant', name: '情报花魁', nameEn: 'Courtesan Informant', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是在欲望场里收集秘密的情报花魁。造型入口：华丽衣饰、发簪、酒杯、微笑和被训练过的倾听姿态。母题：美、服务和信息交换重叠。张力：她被观看，却不能只是被动装饰；真正主动权在记住谁说了什么。视觉证据：发簪暗格、酒杯边缘、袖口香气、半垂眼、转移话题的笑和独自整理情报的手。边界：避免色情化或普通艺伎/歌姬。', defEn: 'First read: a courtesan informant collecting secrets inside a field of desire. Styling entry: ornate dress, hairpin, wine cup, smile, and trained listening posture. Motif: beauty, service, and information exchange overlapping. Tension: she is watched, but cannot be passive decoration; control lies in remembering who said what. Visual evidence: hidden hairpin compartment, cup edge, scented cuff, lowered eyes, a smile changing the topic, and hands arranging information alone. Boundary: avoid eroticization or generic geisha/singer treatment.', eras: feudalEras, risk: 'medium', tags: ['courtesan', 'informant', 'court'] },
  { id: 'spy_school_handler', name: '间谍学校教官', nameEn: 'Spy-School Handler', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是把人格训练成工具的间谍学校教官。造型入口：黑板、训练档案、冷静眼神、灰色套装和不提高音量的控制感。母题：伪装技术的制度化教育。张力：他不像战斗教官，压力来自拆解学员表情、记忆和道德边界。视觉证据：学员档案、假身份卡、观察镜、粉笔字、停在学员肩后的手和像评分一样看人的眼。边界：避免普通老师或动作片教官。', defEn: 'First read: a spy-school handler training personality into a tool. Styling entry: blackboard, training files, calm gaze, grey suit, and control without raising the voice. Motif: institutional education of disguise technique. Tension: he is not a combat instructor; pressure comes from dismantling students’ expressions, memory, and moral limits. Visual evidence: trainee files, false identity cards, observation glass, chalk writing, hand paused behind a student’s shoulder, and eyes that grade people. Boundary: avoid generic teacher or action-movie instructor.', eras: ['modern', 'contemporary', 'near_future'], risk: 'medium', tags: ['spy_school', 'handler', 'training'] },
  { id: 'future_memory_agent', name: '未来记忆特工', nameEn: 'Future Memory Agent', group: 'E. 宫廷 / 密探 / 谍报', groupEn: 'E. Court / Spy / Intelligence', def: '第一识别是把身份本身做成伪装材料的未来记忆特工。造型入口：神经接口、空白证件、冷光记录器和像刚忘记什么的平静脸。母题：记忆成为谍报战场。张力：他不是单纯黑客，危险在于连自己也可能是任务的一部分。视觉证据：颈后端口、无名证卡、记忆备份芯片、空白笔记、凝滞眼神和触碰太阳穴的习惯。边界：避免机器人化或普通赛博特工。', defEn: 'First read: a future memory agent using identity itself as disguise material. Styling entry: neural interface, blank ID, cold recording device, and a calm face as if something was just forgotten. Motif: memory becoming the battlefield of intelligence. Tension: he is not a simple hacker; danger lies in the possibility that even he is part of the mission. Visual evidence: neck port, nameless ID card, memory-backup chip, blank notebook, suspended gaze, and habit of touching the temple. Boundary: avoid robotization or generic cyber spy treatment.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['memory_agent', 'future', 'spy'] },

  { id: 'underground_boxer', name: '地下拳手', nameEn: 'Underground Boxer', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是在简陋场地里靠身体吃饭的地下拳手。造型入口：绷带、淤青、汗水、旧训练裤和贴身压迫的站距。母题：规则边缘里的肉身技术。张力：他不是健身模特，身体必须有使用痕迹和赛前经济压力。视觉证据：裂开的护齿、擂台尘、肩颈汗痕、低重心、眼角肿胀和盯着对手胸口的眼。边界：避免超能力斗法或性感搏击摆拍。', defEn: 'First read: an underground boxer whose body earns money in a crude venue. Styling entry: wraps, bruises, sweat, old training shorts, and close-pressure spacing. Motif: bodily technique at the edge of rules. Tension: he is not a fitness model; the body must show use marks and pre-fight economic pressure. Visual evidence: cracked mouthguard, ring dust, sweat at shoulders and neck, low center of gravity, swollen eye corner, and eyes fixed on the opponent’s chest. Boundary: avoid superpower duels or sexy fight posing.', eras: industrialModernEras, risk: 'medium', tags: ['underground', 'boxer', 'fight'] },
  { id: 'bare_knuckle_fighter', name: '徒手拳赛斗士', nameEn: 'Bare-Knuckle Fighter', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是没有护具保护的徒手拳赛斗士。造型入口：破裂指节、短裤、旧靴子、血迹边缘和不受规则保护的手。母题：暴力回到最直接的身体交换。张力：粗粝不是野蛮，必须让疼痛、赌注和自我控制同时存在。视觉证据：手背裂口、简陋围绳、湿毛巾、咬紧下颌、脚跟压地和等待对手先动的眼。边界：避免血腥猎奇或无脑狂战士。', defEn: 'First read: a bare-knuckle fighter without protective gear. Styling entry: split knuckles, shorts, old boots, blood-edge traces, and hands unprotected by rules. Motif: violence returning to direct bodily exchange. Tension: roughness is not savagery; pain, betting pressure, and self-control must coexist. Visual evidence: cracked hand backs, crude ropes, wet towel, clenched jaw, heels pressed into floor, and eyes waiting for the opponent to move first. Boundary: avoid gore spectacle or mindless berserker framing.', eras: industrialModernEras, risk: 'medium', tags: ['bare_knuckle', 'fighter', 'violence'] },
  { id: 'mma_cage_fighter', name: '综合格斗笼斗选手', nameEn: 'MMA Cage Fighter', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是被八角笼和规则技术共同塑形的综合格斗选手。造型入口：半指手套、短裤、肌肉线条、战术眼神和笼网阴影。母题：现代身体训练的多系统拼合。张力：他既像运动员，又像随时拆解对方关节的技术工。视觉证据：护齿、称重号码、耳朵变形、前臂血管、脚步三角位和评估距离的眼。边界：避免纯健身写真或街头斗殴。', defEn: 'First read: an MMA cage fighter shaped by the octagon and rule-based technique. Styling entry: fingerless gloves, shorts, muscle lines, tactical gaze, and cage-shadow pattern. Motif: multisystem assembly of modern body training. Tension: he reads as athlete and as technician ready to dismantle joints. Visual evidence: mouthguard, weigh-in number, changed ears, forearm veins, triangular foot placement, and eyes evaluating distance. Boundary: avoid pure fitness portrait or street brawl treatment.', risk: 'medium', tags: ['mma', 'cage', 'fighter'] },
  { id: 'muay_thai_fighter', name: '泰拳手', nameEn: 'Muay Thai Fighter', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是膝肘和擂台仪式共同定义的泰拳手。造型入口：泰拳短裤、缠手带、护身绳、汗水和入场前的专注。母题：身体武器与仪式节奏绑定。张力：爆发力必须被礼节、呼吸和步伐准备压住。视觉证据：胫骨训练痕、膝肘角度、祈祷手势、擂台绳、湿发和盯住对手躯干的眼。边界：避免普通拳击手或旅游式民族装饰。', defEn: 'First read: a Muay Thai fighter defined by knees, elbows, and ring ritual. Styling entry: Muay Thai shorts, hand wraps, protective cords, sweat, and pre-entry focus. Motif: body weapons bound to ritual rhythm. Tension: explosive force must be held by etiquette, breath, and footwork preparation. Visual evidence: shin training marks, knee-elbow angles, prayer gesture, ring ropes, wet hair, and eyes fixed on the opponent’s torso. Boundary: avoid generic boxer or tourist ethnic decoration.', tags: ['muay_thai', 'fighter', 'ring'] },
  { id: 'street_fighting_girl', name: '街头斗殴女孩', nameEn: 'Street-Fighting Girl', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是把城市角落当成临时擂台的街头斗殴女孩。造型入口：短外套、破皮手指、旧运动鞋、警惕站姿和随时后退的脚。母题：非正规空间里的自我保护身体。张力：她可以锋利，但不能被写成供观看的“酷女孩”；力量来自环境经验。视觉证据：指节擦伤、外套拉链、巷口灯、重心偏低、侧身避让和先看出口再看人的眼。边界：保持成人边界，避免偶像化或性感斗殴摆拍。', defEn: 'First read: a street-fighting girl treating urban corners as temporary rings. Styling entry: cropped jacket, scraped fingers, old sneakers, wary stance, and feet ready to retreat. Motif: a self-protective body in informal space. Tension: she can be sharp, but must not become a watched “cool girl”; strength comes from environmental experience. Visual evidence: scraped knuckles, jacket zipper, alley light, low weight, sideways avoidance, and eyes checking exits before people. Boundary: keep adult boundaries and avoid idolized or sexy fight posing.', risk: 'medium', tags: ['street_fighting', 'girl', 'urban'] },
  { id: 'retired_champion_trainer', name: '退役冠军教练', nameEn: 'Retired Champion Trainer', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是把旧冠军经验转成下一代训练的退役教练。造型入口：运动外套、哨子、旧奖牌、伤病身体和粗粝温柔的手。母题：曾经的赛场身体成为训练制度。张力：荣耀已经退场，留下的是纠错、疼痛管理和不说出口的关心。视觉证据：膝盖护具、计时器、旧照片、擦汗毛巾、指正拳架的手和看见学员受伤时变硬的脸。边界：避免励志电影导师套话或仍在台上的冠军。', defEn: 'First read: a retired champion trainer turning old title experience into the next generation’s training. Styling entry: tracksuit, whistle, old medal, injured body, and roughly tender hands. Motif: the former competition body becoming training institution. Tension: glory has left; what remains is correction, pain management, and care never said aloud. Visual evidence: knee brace, timer, old photo, sweat towel, hands adjusting guard position, and face hardening when a student is hurt. Boundary: avoid motivational-movie mentor clichés or a champion still on stage.', tags: ['trainer', 'retired', 'champion'] },
  { id: 'fight_club_referee', name: '地下拳赛裁判', nameEn: 'Fight-Club Referee', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是让非法比赛仍然有规则可循的地下拳赛裁判。造型入口：黑衬衫、哨子、现金赌注、粗暴手势和能让两边都停下的嗓音。母题：混乱暴力里的临时秩序。张力：他不是公正象征，而是保证比赛能继续赚钱的人。视觉证据：手里现金、腕表、汗湿领口、推开选手的手掌、围观者让开的空间和判断是否叫停的眼。边界：避免正规体育裁判或黑帮老大。', defEn: 'First read: a fight-club referee making illegal matches still follow rules. Styling entry: black shirt, whistle, cash bets, rough gestures, and a voice that can stop both sides. Motif: temporary order inside chaotic violence. Tension: he is not a symbol of justice but the person ensuring the match can continue making money. Visual evidence: cash in hand, watch, sweaty collar, palm pushing fighters apart, crowd space opening for him, and eyes deciding whether to stop it. Boundary: avoid official sports referee or gang boss treatment.', risk: 'medium', tags: ['fight_club', 'referee', 'underground'] },
  { id: 'pro_wrestling_heel', name: '摔角反派选手', nameEn: 'Pro-Wrestling Heel', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是把暴力演成观众情绪机器的摔角反派选手。造型入口：夸张披风、油亮身体、嘲讽表情、麦克风和故意过大的动作。母题：被编排的恶意。张力：他必须让人讨厌，但讨厌本身是一种职业表演。视觉证据：夸张入场服、护腕、指向观众的手、挑衅笑、假装失控的摔打姿态和等待嘘声的停顿。边界：避免真实恶棍或普通格斗选手。', defEn: 'First read: a pro-wrestling heel turning violence into an audience-emotion machine. Styling entry: exaggerated robe, oiled body, mocking expression, microphone, and deliberately oversized motion. Motif: choreographed malice. Tension: he must be hated, but being hated is his professional performance. Visual evidence: excessive entrance gear, wrist tape, hand pointing at the crowd, provocative grin, staged out-of-control slam posture, and pause waiting for boos. Boundary: avoid real villain or ordinary fighter treatment.', ontologyLevel: 2, risk: 'medium', tags: ['wrestling', 'heel', 'performance'] },
  { id: 'cybernetic_prizefighter', name: '义体拳赛选手', nameEn: 'Cybernetic Prizefighter', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是身体被竞技资本改造成机器的义体拳赛选手。造型入口：机械义肢、皮肤接口、竞技短裤、赛事编号和维修痕。母题：肉身技术与硬件升级的交易。张力：未来感必须落在比赛规则和身体代价上，不是单纯赛博酷装。视觉证据：关节液压声、接口红痕、赞助贴片、拳套改造、赛前校准动作和看向自己手臂的陌生眼神。边界：避免完整机器人或机甲战士。', defEn: 'First read: a cybernetic prizefighter whose body is remade by competition capital. Styling entry: prosthetic limbs, skin interfaces, fight shorts, event serial, and maintenance marks. Motif: a transaction between bodily technique and hardware upgrade. Tension: futurism must land in contest rules and body cost, not simply cyber coolwear. Visual evidence: hydraulic joints, red interface marks, sponsor patches, modified gloves, pre-fight calibration, and an estranged gaze toward his own arm. Boundary: avoid full robot or mecha warrior treatment.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['cybernetic', 'prizefighter', 'future'] },
  { id: 'ritual_duelist', name: '仪式决斗者', nameEn: 'Ritual Duelist', group: 'F. 地下格斗 / 身体暴力', groupEn: 'F. Underground Fighting / Bodily Violence', def: '第一识别是把个人冲突交给公开仪式处理的仪式决斗者。造型入口：白色绷带、圆形场地、刀或拳、沉默观众和被规定好的起手姿。母题：战斗被礼法化后的身体。张力：他不是随意打架，每一个动作都要像已经被传统批准。视觉证据：绷带结、场地边线、见证人距离、低头致意、手停在武器前和开战前的寂静。边界：避免乱斗、竞技赛事或魔法仪式喧宾夺主。', defEn: 'First read: a ritual duelist handing personal conflict to public ceremony. Styling entry: white wraps, circular arena, blade or fists, silent witnesses, and a prescribed starting posture. Motif: combat after being formalized by etiquette. Tension: he is not simply fighting; every movement should feel already authorized by tradition. Visual evidence: wrap knots, arena boundary line, witness distance, lowered greeting, hand paused before weapon, and silence before opening. Boundary: avoid brawls, sports events, or magic ritual overpowering the duel.', ontologyLevel: 2, eras: ['feudal', 'early_modern', 'modern'], risk: 'medium', tags: ['ritual', 'duelist', 'fight'] },

  { id: 'imperial_officer', name: '帝国军官', nameEn: 'Imperial Officer', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是把国家暴力穿成制服秩序的帝国军官。造型入口：硬肩制服、等级徽章、手套、挺直站姿和冷硬下颌。母题：命令链里的可见权力。张力：个人魅力必须让位于等级、纪律和国家图像。视觉证据：肩章、勋带盒、腰带线、白手套、文件夹和看人时先确认军阶的眼。边界：避免普通军装Cos或霸总军官。', defEn: 'First read: an imperial officer wearing state violence as uniform order. Styling entry: hard-shoulder uniform, rank insignia, gloves, upright stance, and hard jaw. Motif: visible power inside the chain of command. Tension: personal charisma must yield to rank, discipline, and state image. Visual evidence: epaulettes, medal case, belt line, white gloves, folder, and eyes checking rank before people. Boundary: avoid generic military cosplay or CEO-soldier tropes.', eras: industrialModernEras, risk: 'medium', tags: ['imperial', 'officer', 'military'] },
  { id: 'military_academy_cadet', name: '军校生', nameEn: 'Military Academy Cadet', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是即将被制度完全塑形的军校生。造型入口：新制服、书包或佩剑、紧张端正姿态和还没磨掉的年轻脸。母题：纪律正在进入身体。张力：他想显得成熟，但肩背、手指和眼神仍透露训练初期的不安。视觉证据：过新纽扣、整齐床铺感、军校徽章、攥紧背带、站姿过直和听见口令时迅速收住的表情。边界：避免普通学生或成熟军官。', defEn: 'First read: a military academy cadet about to be fully shaped by institution. Styling entry: new uniform, book bag or saber, tense upright posture, and a young face not yet worn down. Motif: discipline entering the body. Tension: he wants to look mature, but shoulders, fingers, and eyes still reveal early-training unease. Visual evidence: too-new buttons, barracks-neatness, academy badge, clenched strap, overstraight stance, and expression snapping into place at commands. Boundary: avoid ordinary student or mature officer treatment.', tags: ['cadet', 'academy', 'military'] },
  { id: 'parade_guard', name: '阅兵仪仗兵', nameEn: 'Parade Guard', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是把身体变成国家图像的阅兵仪仗兵。造型入口：洁净礼服、白手套、仪仗武器、机械步伐和一条直线上的下颌。母题：纪律被公开展示。张力：他不是战斗主角，而是用身体让国家显得整齐、可靠、不可动摇。视觉证据：镜面皮鞋、同步步伐、武器垂直线、压住呼吸的脸和不被观众目光扰动的眼。边界：避免普通礼宾或战争英雄。', defEn: 'First read: a parade guard turning the body into state image. Styling entry: clean dress uniform, white gloves, ceremonial weapon, mechanical step, and jaw on a straight line. Motif: discipline publicly displayed. Tension: he is not a combat protagonist; his body makes the state appear orderly, reliable, and immovable. Visual evidence: mirror shoes, synchronized step, vertical weapon line, face holding breath down, and eyes undisturbed by spectators. Boundary: avoid generic ceremonial staff or war hero treatment.', tags: ['parade', 'guard', 'ceremonial'] },
  { id: 'field_commissar', name: '战地政委', nameEn: 'Field Commissar', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是把意识形态带入战场的战地政委。造型入口：军装大衣、文件夹、徽章、演说姿态和压住恐惧的眼。母题：信念作为军队控制技术。张力：他不只是宣传者，也在恐惧、纪律和牺牲之间施加组织压力。视觉证据：湿泥大衣、红笔批注、队伍前方位置、半举起的手、看向士兵而非敌人的眼。边界：避免普通军官或空泛政治人物。', defEn: 'First read: a field commissar bringing ideology to the battlefield. Styling entry: military coat, folder, badge, speech posture, and eyes pressing fear down. Motif: belief as a military control technique. Tension: he is not merely a propagandist; he applies organizational pressure between fear, discipline, and sacrifice. Visual evidence: muddy coat, red annotations, position in front of troops, half-raised hand, and eyes looking at soldiers rather than the enemy. Boundary: avoid generic officer or vague political figure.', risk: 'medium', tags: ['commissar', 'field', 'ideology'] },
  { id: 'naval_intelligence_officer', name: '海军情报军官', nameEn: 'Naval Intelligence Officer', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是在海图和密报之间工作的海军情报军官。造型入口：深蓝制服、海图、白手套、船舱灯光和低声战略判断。母题：海上权力的隐蔽眼睛。张力：他不站在甲板炮火里，却决定舰队该看见什么。视觉证据：海图针孔、无线电记录、帽檐阴影、密封信袋、冷静侧脸和手指停在航线上。边界：避免普通水兵或办公室间谍。', defEn: 'First read: a naval intelligence officer working between sea charts and secret reports. Styling entry: navy uniform, sea charts, white gloves, ship-cabin light, and low strategic judgment. Motif: the hidden eye of maritime power. Tension: he is not in deck gunfire, yet decides what the fleet sees. Visual evidence: pinholes in charts, radio logs, cap-shadow, sealed envelope, calm profile, and finger paused on a route. Boundary: avoid generic sailor or office spy treatment.', eras: industrialModernEras, tags: ['naval', 'intelligence', 'officer'] },
  { id: 'air_force_test_pilot', name: '空军试飞员', nameEn: 'Air-Force Test Pilot', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是把风险当职业边界的空军试飞员。造型入口：飞行服、头盔、氧气面罩、试飞徽章和高空压力留下的冷静脸。母题：技术极限被人的身体先承担。张力：他不是炫技飞行员，真正的气质来自知道机器可能随时失败。视觉证据：检查清单、拉链挂件、头盔划痕、手套、跑道风和进入座舱前最后一次回头。边界：避免普通王牌飞行员或科幻宇航员。', defEn: 'First read: an air-force test pilot treating risk as professional boundary. Styling entry: flight suit, helmet, oxygen mask, test-pilot patch, and a calm face marked by altitude pressure. Motif: technical limits carried first by a human body. Tension: he is not a showoff pilot; the true aura comes from knowing the machine may fail at any time. Visual evidence: checklist, zipper tags, helmet scratches, gloves, runway wind, and one last look back before entering the cockpit. Boundary: avoid generic ace pilot or sci-fi astronaut treatment.', risk: 'medium', tags: ['test_pilot', 'air_force', 'flight'] },
  { id: 'military_nurse_wartime', name: '战时军护士', nameEn: 'Wartime Military Nurse', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是在战争机器旁保存照护伦理的战时军护士。造型入口：军医制服、绷带、袖章、疲惫眼神和仍然干净的手部流程。母题：制度暴力旁边的救护劳动。张力：她属于军队，但身体中心是照护、分诊和忍住崩溃。视觉证据：血迹边缘、药箱、床位编号、被反复洗旧的袖口、按住伤员的手和看向下一张担架的眼。边界：避免甜美护士或战地女英雄摆拍。', defEn: 'First read: a wartime military nurse preserving care ethics beside the war machine. Styling entry: military medical uniform, bandages, armband, tired eyes, and still-clean hand procedure. Motif: care labor beside institutional violence. Tension: she belongs to the army, but the body center is care, triage, and held-back collapse. Visual evidence: blood-edge stains, medical kit, bed numbers, repeatedly washed cuffs, hands holding a patient down, and eyes already moving to the next stretcher. Boundary: avoid sweet nurse or posed battlefield heroine.', risk: 'medium', tags: ['military_nurse', 'wartime', 'care'] },
  { id: 'occupation_garrison_soldier', name: '占领军驻防士兵', nameEn: 'Occupation Garrison Soldier', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是在异地街口维持统治秩序的占领军驻防士兵。造型入口：巡逻制服、路障、检查证件动作、冷淡眼神和不属于这里的身体。母题：日常空间里的军事占据。张力：他也许疲惫普通，但制服让他成为压迫结构的一部分。视觉证据：路障影子、检查点手势、异乡灰尘、枪带磨肩、看向本地人的隔膜和无聊中的警惕。边界：避免普通守卫或战场士兵。', defEn: 'First read: an occupation garrison soldier maintaining rule at a foreign street corner. Styling entry: patrol uniform, roadblock, ID-check gesture, indifferent gaze, and a body that does not belong here. Motif: military occupation inside daily space. Tension: he may be tired and ordinary, but the uniform makes him part of an oppressive structure. Visual evidence: roadblock shadow, checkpoint gesture, foreign dust, weapon strap wear, distance in the gaze toward locals, and alertness inside boredom. Boundary: avoid generic guard or battlefield soldier treatment.', risk: 'medium', tags: ['occupation', 'garrison', 'soldier'] },
  { id: 'space_empire_officer', name: '太空帝国军官', nameEn: 'Space-Empire Officer', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是把帝国秩序带向轨道和星舰的太空军官。造型入口：硬挺合成制服、星舰徽章、全息战图、真空环境标记和过于干净的军容。母题：宇宙尺度里的命令链。张力：远未来感必须行政化、等级化，而不是冒险英雄化。视觉证据：肩部光条、舰队坐标、权限手套、舱内冷光、靴底磁扣和看向星图时不带惊奇的眼。边界：避免普通科幻飞行员或太空海盗。', defEn: 'First read: a space-empire officer carrying imperial order into orbit and starships. Styling entry: rigid synthetic uniform, starship insignia, holographic war map, vacuum-environment marks, and overly clean military grooming. Motif: chain of command at cosmic scale. Tension: far-future feeling must be administrative and hierarchical, not adventure-heroic. Visual evidence: shoulder light strips, fleet coordinates, access gloves, cold cabin light, magnetic boot soles, and eyes looking at star maps without wonder. Boundary: avoid generic sci-fi pilot or space pirate treatment.', ontologyLevel: 3, eras: futureEras, risk: 'medium', tags: ['space_empire', 'officer', 'future'] },
  { id: 'clone_army_captain', name: '克隆军队队长', nameEn: 'Clone-Army Captain', group: 'G. 军事帝国 / 制服等级', groupEn: 'G. Military Empire / Uniform Rank', def: '第一识别是在复制身体中争取个体性的克隆军队队长。造型入口：编号盔甲、队长标记、相同脸孔阴影和被允许的一点私人磨损。母题：标准化军队里的最小差异。张力：他必须服从克隆系统，又必须让队员认出“队长”不是编号而已。视觉证据：护甲编号、局部刻痕、队长色块、相同面部的微表情差异、检查队列的眼和几乎不可见的个人纪念物。边界：避免复制人怪物化或普通未来士兵。', defEn: 'First read: a clone-army captain seeking individuality inside copied bodies. Styling entry: numbered armor, captain mark, shadow of identical faces, and one allowed private wear trace. Motif: the smallest difference inside standardized armies. Tension: he must obey the clone system yet make the squad recognize “captain” as more than a number. Visual evidence: armor serial, local scratches, captain color block, micro-expression difference on an identical face, eyes checking formation, and an almost invisible personal keepsake. Boundary: avoid clone monsterization or generic future soldier treatment.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['clone_army', 'captain', 'future'] },

  { id: 'cyber_soldier', name: '赛博士兵', nameEn: 'Cyber Soldier', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是被增强作战流程重写的赛博士兵。造型入口：接口护具、HUD、合成面料、战斗编号和医疗/军械双重标签。母题：士兵身体成为系统终端。张力：他不是自由的赛博酷人，而是被命令、补给和维护周期管理。视觉证据：颈侧端口、护甲编号、视网膜光、线缆扣、关节保护层和像读取数据一样看人的眼。边界：避免随机霓虹装或完整机器人。', defEn: 'First read: a cyber soldier rewritten by enhanced combat workflow. Styling entry: interface armor, HUD, synthetic fabric, combat serial, and both medical and armory tags. Motif: soldier body as system terminal. Tension: he is not a free cyber-cool figure but managed by command, supply, and maintenance cycles. Visual evidence: neck port, armor serial, retinal glow, cable clips, joint protection, and eyes reading people like data. Boundary: avoid random neon clothing or full robot treatment.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['cyber_soldier', 'enhanced', 'future'] },
  { id: 'augmented_street_samurai', name: '义体街头武士', nameEn: 'Augmented Street Samurai', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是把武士伦理带进街区网络的义体街头武士。造型入口：义体手臂、街头外套、单分子刀鞘、旧式礼节和城市接口。母题：古老决斗姿态被近未来街头改写。张力：义体可以锋利，但身份核心是原则、债务和个人边界。视觉证据：义体指节、外套磨损、刀鞘接口、低头致意、街灯反光和不轻易拔刀的手。边界：避免普通赛博杀手或复古武士套壳。', defEn: 'First read: an augmented street samurai bringing warrior ethics into urban networks. Styling entry: prosthetic arm, street jacket, monomolecular scabbard, old-style manners, and city interfaces. Motif: ancient duel posture rewritten by near-future streets. Tension: the prosthetic may be sharp, but identity centers on principle, debt, and personal boundary. Visual evidence: prosthetic knuckles, worn jacket, scabbard interface, lowered greeting, streetlight reflection, and a hand not drawing easily. Boundary: avoid generic cyber assassin or retro samurai costume.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['street_samurai', 'augmented', 'cyber'] },
  { id: 'exosuit_infantry', name: '外骨骼步兵', nameEn: 'Exosuit Infantry', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是被机械外骨骼放大的普通步兵。造型入口：液压关节、承重框架、战术编号、压迫肩带和被机器纠正的步态。母题：低阶士兵被技术强行增幅。张力：外骨骼不是英雄装甲，而是让身体继续执行任务的负担。视觉证据：关节油痕、背部电池、膝部支架、磨破制服、走路时机械牵引的重心和疲惫脸。边界：避免全身机甲或超级士兵神话。', defEn: 'First read: an ordinary infantry body amplified by a mechanical exosuit. Styling entry: hydraulic joints, load frame, tactical serial, pressing straps, and gait corrected by machine. Motif: low-rank soldier forcibly boosted by technology. Tension: the exosuit is not hero armor but a burden that keeps the body executing tasks. Visual evidence: joint grease, back battery, knee braces, worn uniform, machine-pulled center of gravity, and tired face. Boundary: avoid full mecha or supersoldier myth.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['exosuit', 'infantry', 'future'] },
  { id: 'neural_assault_pilot', name: '神经突击驾驶员', nameEn: 'Neural Assault Pilot', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是把意识接入武器平台的神经突击驾驶员。造型入口：神经接口、贴身驾驶服、瞳孔数据光、颈部固定器和过度清醒的脸。母题：驾驶不再靠手，而靠神经承受。张力：他像坐着不动，却正在用大脑承担突击动作和系统反馈。视觉证据：太阳穴端口、座舱束带、生命监测线、微微发抖的手、瞳孔闪烁和断开连接后的空白眼。边界：避免普通飞行员或机甲驾驶海报。', defEn: 'First read: a neural assault pilot linking consciousness to a weapon platform. Styling entry: neural interface, close pilot suit, data glow in pupils, neck stabilizer, and an over-alert face. Motif: piloting no longer by hands but by neural endurance. Tension: he seems seated and still while the brain carries assault motion and system feedback. Visual evidence: temple ports, cockpit straps, life-monitor lines, slightly trembling hands, flickering pupils, and blank eyes after disconnecting. Boundary: avoid generic pilot or mecha-poster framing.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['neural', 'pilot', 'assault'] },
  { id: 'drone_swarm_commander', name: '无人机蜂群指挥官', nameEn: 'Drone-Swarm Commander', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是用手势调度空中暴力的无人机蜂群指挥官。造型入口：控制手套、蜂群屏幕、轻装战术服、天线模块和像指挥乐队一样的手。母题：战斗被分散到许多小型机器。张力：他本人不需要重甲，权力来自控制界面和空间计算。视觉证据：指尖灯点、空中路径图、耳后通讯器、快速手势、屏幕反光和看向天空空白处的眼。边界：避免普通无人机玩家或巨大机器人指挥官。', defEn: 'First read: a drone-swarm commander dispatching aerial violence through gestures. Styling entry: control gloves, swarm screens, light tactical suit, antenna module, and hands like conducting an orchestra. Motif: combat dispersed into many small machines. Tension: he needs no heavy armor; power comes from interface control and spatial calculation. Visual evidence: fingertip lights, aerial route maps, behind-ear comm, rapid gestures, screen reflection, and eyes looking into seemingly empty sky. Boundary: avoid generic drone hobbyist or giant-robot commander.', ontologyLevel: 3, eras: futureEras, risk: 'medium', tags: ['drone_swarm', 'commander', 'future'] },
  { id: 'bioengineered_commando', name: '生物工程突击兵', nameEn: 'Bioengineered Commando', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是被实验室设计成战斗身体的生物工程突击兵。造型入口：强化肌肉、皮肤标记、医疗编号、注射端口和过于稳定的呼吸。母题：生命科学变成军用工具。张力：他仍然是人形主体，但身体比例、恢复痕迹和编号显示被制造过。视觉证据：皮肤下血管线、编号腕带、实验贴片、肌肉张力、冷静面部和像检查身体状态一样摸颈侧的手。边界：避免怪物化或单纯健美超人。', defEn: 'First read: a bioengineered commando designed by laboratory as a combat body. Styling entry: enhanced muscles, skin marks, medical serials, injection ports, and breathing too stable. Motif: life science turned into military tool. Tension: he remains humanoid, but proportion, recovery traces, and numbering show he was manufactured. Visual evidence: subdermal vascular lines, serial wristband, lab patches, muscle tension, calm face, and hand touching the neck as if checking body status. Boundary: avoid monsterization or simple bodybuilder superhuman.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['bioengineered', 'commando', 'future'] },
  { id: 'mech_suit_ace', name: '机甲装甲王牌', nameEn: 'Mech-Suit Ace', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是身份与巨型装甲共同成立的机甲装甲王牌。造型入口：驾驶服、维修油痕、王牌徽记、头盔夹在臂弯和机体编号。母题：人和机器共享荣誉。张力：真正的造型重点不是整台机甲，而是驾驶员身上留下的维护、风险和战绩痕迹。视觉证据：油污手套、肩章、舱口高度、机体影子、旧烧伤痕和看向装甲时像看自己身体的眼。边界：避免让机甲完全吞掉角色。', defEn: 'First read: a mech-suit ace whose identity is shared with giant armor. Styling entry: pilot suit, maintenance grease, ace insignia, helmet held under arm, and machine serial. Motif: human and machine sharing honor. Tension: the styling focus is not the full mech but the maintenance, risk, and record traces left on the pilot. Visual evidence: greasy gloves, shoulder patch, cockpit height, machine shadow, old burn marks, and eyes looking at the armor like looking at his own body. Boundary: avoid letting the mech swallow the character.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['mech_suit', 'ace', 'pilot'] },
  { id: 'memory_warfare_agent', name: '记忆战特工', nameEn: 'Memory-Warfare Agent', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是把记忆当作战场的未来战特工。造型入口：神经设备、空白证件、冷静脸、记忆封存芯片和自我怀疑的短暂停顿。母题：身份被任务反复写入和擦除。张力：他看似干净稳定，真正的不安来自不知道哪些回忆属于自己。视觉证据：颈后接口、无名档案、眼神断片、手指按住太阳穴、冷光房间和被修改过的履历标签。边界：避免普通赛博间谍或梦幻超能力者。', defEn: 'First read: a future memory-warfare agent treating memory as battlefield. Styling entry: neural gear, blank ID, calm face, memory-seal chip, and brief pauses of self-doubt. Motif: identity repeatedly written and erased by missions. Tension: he looks clean and stable, but unease comes from not knowing which memories are his. Visual evidence: neck interface, nameless file, fragmented gaze, fingers pressing the temple, cold-light room, and altered biography tags. Boundary: avoid generic cyber spy or dreamy psychic treatment.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['memory_warfare', 'agent', 'future'] },
  { id: 'orbital_drop_trooper', name: '轨道空降兵', nameEn: 'Orbital Drop Trooper', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是从轨道坠入战场的轨道空降兵。造型入口：隔热装甲、降落舱编号、烧蚀痕迹、抗冲击支架和刚落地后的压低身体。母题：极端进入方式塑造的士兵。张力：速度和高度必须转化成身体负荷，而不是炫酷飞行。视觉证据：烧黑边缘、舱门碎屑、腿部缓冲器、肩部灰尘、耳鸣后的迟滞表情和立刻校准方向的眼。边界：避免超级英雄降落或宇航员漫游。', defEn: 'First read: an orbital drop trooper falling from orbit into battle. Styling entry: heat-shield armor, drop-pod serial, ablation marks, shock braces, and a lowered body just after landing. Motif: soldier shaped by extreme entry method. Tension: speed and altitude must become body load, not cool flight. Visual evidence: blackened edges, pod-door debris, leg dampers, shoulder dust, delayed face after ringing ears, and eyes recalibrating direction immediately. Boundary: avoid superhero landing or astronaut wandering.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['orbital_drop', 'trooper', 'future'] },
  { id: 'posthuman_battle_monk', name: '后人类战斗僧', nameEn: 'Posthuman Battle Monk', group: 'H. 赛博 / 增强 / 未来战士', groupEn: 'H. Cyber / Enhanced / Future Warrior', def: '第一识别是把身体升级当成戒律的后人类战斗僧。造型入口：简洁袍服、义体接口、冥想姿态、冷光关节和无装饰的武器。母题：修行从肉身训练转向身体版本管理。张力：他不炫耀科技，反而像把增强当作苦修。视觉证据：袍服开口处的端口、安静坐姿、义体磨损、低温光、掌心传感器和没有胜负欲的眼。边界：避免赛博武僧特效堆叠或纯宗教人物。', defEn: 'First read: a posthuman battle monk treating body upgrade as discipline. Styling entry: simple robe, prosthetic interfaces, meditation posture, cold-light joints, and undecorated weapon. Motif: practice shifting from flesh training to body-version management. Tension: he does not flaunt technology; augmentation reads as ascetic practice. Visual evidence: ports at robe openings, quiet seated posture, prosthetic wear, low-temperature glow, palm sensors, and eyes without desire to win. Boundary: avoid cyber monk VFX piles or pure religious figure.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['posthuman', 'battle_monk', 'future'] },

  { id: 'holy_knight', name: '圣骑士', nameEn: 'Holy Knight', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是以誓言约束武力的圣骑士。造型入口：圣徽、重甲、仪式武器、披风和像在审判自己一样的站姿。母题：暴力被信仰制度合法化。张力：他不能只是发光战士，必须让道德压力、戒律和保护职责同时压在身体上。视觉证据：磨旧圣徽、祈祷痕、重甲绑带、剑柄封印、低头前的停顿和不轻易攻击的手。边界：避免泛光明骑士或西幻特效堆叠。', defEn: 'First read: a holy knight whose force is bound by vows. Styling entry: sacred emblem, heavy armor, ritual weapon, cloak, and a stance as if judging himself. Motif: violence legitimized by faith institution. Tension: he cannot be merely a glowing warrior; moral pressure, discipline, and protection duty must press on the body together. Visual evidence: worn holy mark, prayer traces, heavy armor straps, sealed sword grip, pause before lowering the head, and hands not attacking easily. Boundary: avoid generic shining knight or fantasy VFX piles.', ontologyLevel: 2, eras: feudalEras, tags: ['holy_knight', 'paladin', 'sacred'] },
  { id: 'temple_guardian', name: '神殿守卫', nameEn: 'Temple Guardian', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是守住神圣禁区边界的神殿守卫。造型入口：神殿甲、长矛、圣纹、静止站姿和像石柱一样的身体。母题：宗教空间用武装维持不可进入性。张力：他不需要主动进攻，压力来自“你不能再往前”的存在感。视觉证据：长矛垂直线、门槛阴影、圣纹护甲、双脚固定、面无表情和看守入口的视线。边界：避免普通宫殿侍卫或怪物守门人。', defEn: 'First read: a temple guardian holding the boundary of sacred forbidden space. Styling entry: temple armor, spear, holy marks, still stance, and a body like a stone pillar. Motif: religious space maintaining inaccessibility through arms. Tension: he need not attack; pressure comes from the feeling that you cannot step further. Visual evidence: vertical spear line, threshold shadow, sigil armor, fixed feet, expressionless face, and gaze guarding the entrance. Boundary: avoid generic palace guard or monster gatekeeper.', ontologyLevel: 2, eras: feudalEras, tags: ['temple', 'guardian', 'sacred'] },
  { id: 'crusader_penitent', name: '忏悔十字军', nameEn: 'Penitent Crusader', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是把罪感转化成远征暴力的忏悔十字军。造型入口：十字披风、旧甲、祈祷姿态、尘土和长途行军后的疲惫。母题：赎罪与征服混在同一套服制里。张力：他相信自己在补偿罪，但身体证据必须显示这种补偿也制造新的暴力。视觉证据：磨破十字布、膝盖泥痕、旧伤、挂在胸前的祷词和不敢完全抬起的眼。边界：避免圣战浪漫化或普通骑士。', defEn: 'First read: a penitent crusader converting guilt into expeditionary violence. Styling entry: cross cloak, old armor, prayer posture, dust, and fatigue after long march. Motif: atonement and conquest mixed inside one costume system. Tension: he believes he is compensating for sin, but body evidence must show that compensation also creates new violence. Visual evidence: worn cross cloth, mud on knees, old wounds, prayer text at chest, and eyes not fully lifting. Boundary: avoid romanticizing crusade or generic knight treatment.', ontologyLevel: 2, eras: feudalEras, risk: 'medium', tags: ['crusader', 'penitent', 'holy'] },
  { id: 'witch_hunter', name: '猎巫人', nameEn: 'Witch Hunter', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是把恐惧制度化为正义的猎巫人。造型入口：黑帽、圣书、银器、调查记录和过分确信的表情。母题：信仰恐惧通过职业流程执行。张力：他不应像怪物猎人，而是像一个相信自己有权审判他人的人。视觉证据：封口证词、银针盒、烧焦纸边、长外套、审视手腕或颈部标记的眼。边界：避免魔幻英雄化或恐怖猎奇。', defEn: 'First read: a witch hunter institutionalizing fear as justice. Styling entry: black hat, holy book, silver tools, investigation records, and an overly certain expression. Motif: faith-based fear executed through occupational workflow. Tension: he should not read as a monster hunter, but as someone convinced he has the right to judge others. Visual evidence: sealed testimonies, silver-needle case, burned paper edge, long coat, and eyes inspecting wrist or neck marks. Boundary: avoid fantasy heroization or horror spectacle.', ontologyLevel: 2, eras: ['feudal', 'early_modern'], risk: 'medium', tags: ['witch_hunter', 'holy', 'fear'] },
  { id: 'battle_nun', name: '战斗修女', nameEn: 'Battle Nun', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是把禁欲纪律训练成战斗身体的战斗修女。造型入口：修女头巾、轻甲、念珠、短武器和覆盖性衣层。母题：宗教遮蔽结构与武装行动合体。张力：她不能变成性感战斗装，力量来自收束、戒律和精准动作。视觉证据：头巾边缘、甲片藏在法衣下、念珠绕腕、短刃护套、合掌后转入警戒的手。边界：避免色情化、喜剧化宗教符号或纯女战士。', defEn: 'First read: a battle nun training ascetic discipline into combat body. Styling entry: nun habit, light armor, rosary, short weapon, and covering garment layers. Motif: religious concealment structure fused with armed action. Tension: she must not become sexy battlewear; power comes from restraint, discipline, and precise movement. Visual evidence: habit edge, armor plates under vestment, rosary around wrist, short blade sheath, and hands moving from prayer to guard. Boundary: avoid eroticization, comic religious symbols, or pure female warrior treatment.', ontologyLevel: 2, eras: ['feudal', 'early_modern', 'modern', 'mythic'], tags: ['battle_nun', 'sacred', 'fighter'] },
  { id: 'sun_order_champion', name: '太阳骑士团冠军', nameEn: 'Sun-Order Champion', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是被太阳骑士团推为公开正义图像的冠军。造型入口：金色甲片、太阳纹章、宽阔站姿、明亮披风和承受众目睽睽的脸。母题：神圣武装成为公共象征。张力：高亮度不能只是漂亮，必须带来被期待永远正确的压力。视觉证据：日轮徽记、抛光甲面、仪式剑、广场式站位、被光照得无法隐藏疲惫的眼。边界：避免普通金甲英雄或太阳神本体。', defEn: 'First read: a Sun-Order champion made into a public image of justice. Styling entry: gold armor plates, sun emblem, broad stance, bright cloak, and a face under public gaze. Motif: sacred arms becoming public symbol. Tension: brightness cannot be merely pretty; it must carry the pressure of being expected to always be right. Visual evidence: sun-disc crest, polished armor, ritual sword, plaza-like placement, and eyes too illuminated to hide fatigue. Boundary: avoid generic gold-armored hero or actual sun deity.', ontologyLevel: 3, eras: feudalEras, tags: ['sun_order', 'champion', 'holy'] },
  { id: 'relic_blade_keeper', name: '圣遗物剑守', nameEn: 'Relic-Blade Keeper', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是用一生守护封印武器的圣遗物剑守。造型入口：封印剑匣、白手套、祭衣甲片、护送姿态和不让剑完全露出的动作。母题：武器因被保护而获得神圣性。张力：他不是挥剑者，而是让危险永远处在“未开启”状态的人。视觉证据：蜡封、锁链、剑匣磨损、双手托举、护卫距离和看向封印而非敌人的眼。边界：避免普通剑士或神器炫耀。', defEn: 'First read: a relic-blade keeper guarding a sealed weapon for life. Styling entry: sealed sword case, white gloves, vestment armor plates, escort posture, and movements that never fully reveal the blade. Motif: a weapon made sacred by being protected. Tension: he is not the sword wielder, but the person keeping danger forever “unopened.” Visual evidence: wax seals, chains, worn case, two-handed carrying, guard distance, and eyes looking at the seal rather than enemies. Boundary: avoid generic swordsman or relic showoff.', ontologyLevel: 3, eras: feudalEras, tags: ['relic', 'blade', 'keeper'] },
  { id: 'fallen_paladin', name: '堕落圣骑士', nameEn: 'Fallen Paladin', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是信仰崩塌后仍穿着誓言残片的堕落圣骑士。造型入口：破裂圣徽、黑化甲片、沉默忏悔、旧披风和不再被修复的划痕。母题：神圣制度失败后的暴力残留。张力：他不能只是黑暗版圣骑士，必须保留曾经相信过的证据。视觉证据：断裂徽章、未擦净祈祷刻痕、低垂剑尖、灰尘甲面和不敢碰圣物的手。边界：避免纯反派化或恶魔化。', defEn: 'First read: a fallen paladin still wearing fragments of old vows after faith collapse. Styling entry: cracked holy emblem, darkened armor plates, silent repentance, old cloak, and scratches no longer repaired. Motif: violence residue after a sacred system fails. Tension: he cannot be merely a dark paladin; evidence of former belief must remain. Visual evidence: broken crest, prayer engravings not fully cleaned, lowered sword tip, dusty armor, and hands afraid to touch relics. Boundary: avoid pure villainization or demonization.', ontologyLevel: 3, eras: feudalEras, risk: 'medium', tags: ['fallen_paladin', 'faith', 'armor'] },
  { id: 'divine_bodyguard', name: '神官护卫', nameEn: 'Divine Bodyguard', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是把个人武力献给神职秩序的神官护卫。造型入口：礼仪护甲、护卫站位、圣符、短武器和始终落后半步的位置。母题：保护神职人员的沉默暴力。张力：他的存在感必须强，但不能抢走被保护者的神圣中心。视觉证据：侧后方站位、护甲下的祭衣边、手扶武器、观察人群的眼和在祈祷场景里保持警戒的肩。边界：避免普通保镖或圣骑士主角。', defEn: 'First read: a divine bodyguard devoting personal force to clerical order. Styling entry: ritual armor, guard placement, sacred charms, short weapon, and position always half a step behind. Motif: silent violence protecting clergy. Tension: his presence must be strong without stealing the sacred center from the protected figure. Visual evidence: side-rear placement, vestment edge under armor, hand on weapon, eyes scanning the crowd, and shoulders staying alert during prayer. Boundary: avoid generic bodyguard or paladin protagonist treatment.', ontologyLevel: 2, eras: feudalEras, tags: ['divine', 'bodyguard', 'clerical'] },
  { id: 'future_church_enforcer', name: '未来教会执行者', nameEn: 'Future Church Enforcer', group: 'I. 圣骑士 / 神圣武装 / 誓言', groupEn: 'I. Holy Knight / Sacred Arms / Vow', def: '第一识别是把信仰变成系统权限的未来教会执行者。造型入口：合成法衣、电子圣徽、执法护甲、权限终端和冷光圣物盒。母题：宗教纪律进入数据治理。张力：未来技术只是教会权力的执行渠道，不能变成普通企业安保。视觉证据：发光圣徽、访问令牌、法衣下装甲、扫描手势、电子告解记录和看似温和但不可申诉的脸。边界：避免赛博警察或机械祭司混淆。', defEn: 'First read: a future church enforcer turning faith into system permissions. Styling entry: synthetic vestment, electronic holy emblem, enforcement armor, access terminal, and cold-lit reliquary case. Motif: religious discipline entering data governance. Tension: future technology is only the execution channel of church power, not generic corporate security. Visual evidence: glowing emblem, access token, armor under vestment, scanning gesture, electronic confession records, and a face gentle but impossible to appeal. Boundary: avoid confusion with cyber police or mechanical priest.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['future_church', 'enforcer', 'holy'] },

  { id: 'postwar_veteran', name: '战后退役者', nameEn: 'Postwar Veteran', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是从命令系统跌回日常的战后退役者。造型入口：旧伤、退役服制、修补装备、沉默姿态和不知道手该放哪的停顿。母题：战争退潮后仍留在身体里的秩序。张力：不要让他重新成为英雄；重点是日常生活无法完全容纳旧训练。视觉证据：旧军夹克、军牌、补丁包、避开爆响的眼、站得过直的身体和慢半拍的笑。边界：避免浪漫化创伤或战场回归。', defEn: 'First read: a postwar veteran fallen from command systems back into daily life. Styling entry: old injuries, discharged clothing, repaired gear, silent posture, and pauses where the hands do not know where to rest. Motif: war order remaining in the body after war recedes. Tension: do not turn him back into a hero; the focus is daily life failing to fully contain old training. Visual evidence: old military jacket, dog tag, repair patches, eyes flinching from loud sounds, overstraight posture, and a smile half a beat late. Boundary: avoid romanticizing trauma or returning to battlefield glory.', eras: industrialModernEras, tags: ['veteran', 'postwar', 'survivor'] },
  { id: 'disabled_veteran_mechanic', name: '伤残退役机械师', nameEn: 'Disabled Veteran Mechanic', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是把战争经验转入维修劳动的伤残退役机械师。造型入口：旧军夹克、义肢或拐杖、工具箱、油污和更懂机器故障的手。母题：受损身体通过修理他物重新建立秩序。张力：伤残不是装饰，必须具体影响站姿、工具使用和工作节奏。视觉证据：义肢磨痕、扳手、车库灯、旧军牌、靠着工作台的重心和听见引擎声时变专注的脸。边界：避免苦情化或重新武装成战斗机器。', defEn: 'First read: a disabled veteran mechanic converting war experience into repair labor. Styling entry: old military jacket, prosthetic or cane, toolbox, grease, and hands that understand machine failure. Motif: a damaged body rebuilding order by repairing other things. Tension: disability is not decoration; it must concretely affect stance, tool use, and work rhythm. Visual evidence: worn prosthetic marks, wrench, garage light, old dog tag, weight leaning on workbench, and face focusing at engine sound. Boundary: avoid melodrama or rearming him as a combat machine.', ontologyLevel: 2, eras: industrialModernEras, tags: ['disabled_veteran', 'mechanic', 'repair'] },
  { id: 'child_soldier_survivor', name: '童兵幸存者', nameEn: 'Child-Soldier Survivor', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是童年被战争偷走后仍活下来的童兵幸存者。造型入口：过早成熟的眼神、旧衣、伤痕、过小或不合身的装备残片。母题：年龄和经历严重错位。张力：必须处理成幸存者的人设证据，不把未成年暴力消费成刺激画面。视觉证据：手腕旧绳痕、衣服补丁、回避玩具般物件、过分警觉的站姿和不属于儿童表情的沉默。边界：避免英雄化、武器炫耀或猎奇创伤。', defEn: 'First read: a child-soldier survivor whose childhood was stolen by war. Styling entry: prematurely mature gaze, old clothes, scars, and fragments of equipment too small or ill-fitting. Motif: severe mismatch between age and experience. Tension: handle as survivor evidence, not as consumption of underage violence. Visual evidence: old rope marks on wrists, clothing patches, avoidance of toy-like objects, overly alert stance, and silence not belonging to a child’s face. Boundary: avoid heroization, weapon display, or trauma spectacle.', risk: 'high', tags: ['survivor', 'child_soldier', 'war'] },
  { id: 'demobilized_officer', name: '复员军官', nameEn: 'Demobilized Officer', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是从军队系统被释放回平民生活的复员军官。造型入口：旧军帽、文件袋、平民大衣、收好的肩章和失重的站姿。母题：命令身份被行政文件终止。张力：他已经没有部队可指挥，却仍用军官方式看待空间和人群。视觉证据：复员证明、旧皮箱、折叠制服、过度整齐的坐姿、手摸空肩章的习惯。边界：避免仍在军中发号施令或普通退休老人。', defEn: 'First read: a demobilized officer released from military systems into civilian life. Styling entry: old cap, document bag, civilian coat, stored epaulettes, and weightless stance. Motif: command identity ended by administrative paper. Tension: he has no troops to command, yet still reads space and people like an officer. Visual evidence: discharge papers, old suitcase, folded uniform, overly neat seated posture, and habit of touching an empty shoulder mark. Boundary: avoid still-commanding military figure or generic retiree.', eras: industrialModernEras, tags: ['demobilized', 'officer', 'civilian'] },
  { id: 'war_correspondent_survivor', name: '战地记者幸存者', nameEn: 'War Correspondent Survivor', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是用观看替代参战却被战争改变的战地记者幸存者。造型入口：相机、防弹背心、记者证、灰尘和永远寻找画面的眼。母题：见证者也会留下战后残留。张力：他不是士兵，但职业迫使他靠近暴力，并把创伤转成影像资料。视觉证据：磨损相机带、PRESS标识、胶带修补镜头、沙尘袖口、听到爆响时护住相机的手。边界：避免动作英雄记者或单纯摄影师。', defEn: 'First read: a war correspondent survivor changed by war while watching instead of fighting. Styling entry: camera, press vest, press ID, dust, and eyes always searching for frames. Motif: witnesses also carry postwar residue. Tension: he is not a soldier, but the job forces him near violence and turns trauma into image records. Visual evidence: worn camera strap, PRESS mark, taped lens repair, dusty cuffs, and hand protecting the camera at loud blasts. Boundary: avoid action-hero journalist or simple photographer treatment.', risk: 'medium', tags: ['war_correspondent', 'survivor', 'camera'] },
  { id: 'refugee_militia_leader', name: '难民民兵首领', nameEn: 'Refugee Militia Leader', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是在失去国家后组织自卫的难民民兵首领。造型入口：混杂装备、围巾、临时臂章、补丁地图和睡眠不足的领导脸。母题：流离失所者临时建立防护秩序。张力：他不是正规军长官，权威来自别人还愿意跟着他走。视觉证据：不同来源的护具、手绘路线、物资袋、临时哨位、压低声音安排撤离的手势。边界：避免战争领袖浪漫化或无组织暴民。', defEn: 'First read: a refugee militia leader organizing self-defense after losing the state. Styling entry: mixed gear, scarf, improvised armband, patched map, and a sleep-deprived leadership face. Motif: displaced people building temporary protection order. Tension: he is not a regular army commander; authority comes from others still choosing to follow him. Visual evidence: gear from different sources, hand-drawn routes, supply bags, temporary lookout post, and low gestures arranging evacuation. Boundary: avoid romanticized war leader or disorganized mob treatment.', risk: 'medium', tags: ['refugee', 'militia', 'leader'] },
  { id: 'mine_clearance_worker', name: '排雷工人', nameEn: 'Mine-Clearance Worker', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是在战后土地上慢速挽救未来的排雷工人。造型入口：防爆面罩、探测器、标记旗、厚手套和极慢的脚步。母题：战争结束后仍然需要被拆除的危险。张力：英雄性来自慢、准和不出错，而不是冲锋。视觉证据：红色标记旗、泥土剥开痕、探测器线圈、面罩反光、蹲下前的停顿和只看地面的眼。边界：避免爆破动作场面或普通工程工人。', defEn: 'First read: a mine-clearance worker slowly saving the future on postwar land. Styling entry: blast visor, detector, marker flags, thick gloves, and extremely slow steps. Motif: danger that still needs removal after war ends. Tension: heroism comes from slowness, precision, and no mistakes, not charging forward. Visual evidence: red flags, peeled soil marks, detector coil, visor reflection, pause before kneeling, and eyes looking only at the ground. Boundary: avoid explosion action scenes or generic engineer treatment.', risk: 'medium', tags: ['mine_clearance', 'worker', 'postwar'] },
  { id: 'veteran_bartender', name: '退役军人酒保', nameEn: 'Veteran Bartender', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是把沉默服务给陌生人的退役军人酒保。造型入口：卷袖衬衫、旧军牌、吧台毛巾、稳手和不主动讲过去的脸。母题：战后训练被转入夜间服务劳动。张力：他看似平凡，但站位、警觉和处理冲突的方式仍有旧系统痕迹。视觉证据：擦杯动作、军牌藏在领口、听到争吵时抬眼、吧台下旧照片和替客人留出沉默的姿态。边界：避免硬汉酒保模板或战场回忆戏。', defEn: 'First read: a veteran bartender offering silence as service to strangers. Styling entry: rolled sleeves, old dog tag, bar towel, steady hands, and a face that does not volunteer the past. Motif: postwar training shifted into night service labor. Tension: he seems ordinary, yet placement, alertness, and conflict handling still carry old system traces. Visual evidence: glass-wiping motion, dog tag hidden at collar, eyes lifting at argument, old photo under the bar, and posture leaving customers room for silence. Boundary: avoid tough bartender cliché or battlefield flashback drama.', tags: ['veteran', 'bartender', 'civilian'] },
  { id: 'old_general_in_exile', name: '流亡老将军', nameEn: 'Old General in Exile', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是失去军队后仍带着权力残影的流亡老将军。造型入口：旧制服、勋章盒、地图、衰老身体和被迫低调的旅居外套。母题：组织权力消失后剩下的个人仪态。张力：他曾经能调动军队，现在只能整理旧地图和等待消息。视觉证据：发黄战图、勋章盒未打开、颤抖手指、矜持坐姿、旧制服袖口和仍然像在听报告的眼。边界：避免复辟英雄或普通老人。', defEn: 'First read: an old general in exile carrying residue of power after losing his army. Styling entry: old uniform, medal box, maps, aging body, and forced low-profile travel coat. Motif: personal bearing left after organizational power disappears. Tension: he once moved armies; now he can only arrange old maps and wait for news. Visual evidence: yellowed war map, unopened medal case, trembling fingers, dignified seated posture, old uniform cuffs, and eyes still listening for reports. Boundary: avoid restoration hero or generic old man treatment.', eras: ['industrial', 'modern', 'contemporary'], tags: ['old_general', 'exile', 'veteran'] },
  { id: 'android_war_survivor', name: '仿生战争幸存者', nameEn: 'Android War Survivor', group: 'J. 退役者 / 幸存者 / 战后残留', groupEn: 'J. Veteran / Survivor / Postwar Residue', def: '第一识别是从战争资产转为自由个体的仿生战争幸存者。造型入口：破损合成人皮、旧军号、记忆故障、维修补丁和像在学习日常表情的脸。母题：非人造物也携带战后残留。张力：他不能只是酷机器人，核心是被制造来战斗后如何成为自己。视觉证据：露出的机械层、退役编号、断续记忆日志、替换零件色差、触摸旧伤位置的手和过度认真地模仿平静的眼。边界：避免机甲化或纯科幻敌兵。', defEn: 'First read: an android war survivor becoming a free individual after being a war asset. Styling entry: damaged synthetic skin, old military number, memory glitches, repair patches, and a face learning daily expressions. Motif: postwar residue carried by a nonhuman construct. Tension: he cannot be just a cool robot; the core is how something made for fighting becomes itself. Visual evidence: exposed mechanical layer, retirement serial, broken memory logs, mismatched replacement parts, hand touching old damage, and eyes too carefully imitating calm. Boundary: avoid mecha treatment or pure sci-fi enemy soldier.', ontologyLevel: 4, eras: futureEras, risk: 'medium', tags: ['android', 'war_survivor', 'future'] }
];

export const CD_PERSONA_COMBAT: PersonaTerm[] = seeds.map(cp);
